INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `category_id`, `brand_id`, `description`, `short_description`, `price`, `discount_price`, `stock`, `image`, `gallery`, `specs`, `seo_title`, `seo_description`, `seo_keywords`, `sort_order`, `status`, `featured`, `views`, `key_features`, `guarantee`, `created_at`, `updated_at`, `tax_percent`) VALUES (1,'مودم روتر 4G LTE بی‌سیم دی لینک مدل DWR-M921','dlink-dwr-m921','DL-M921',26,5,'مودم روتر 4G LTE دی‌لینک با امکان اتصال مستقیم سیم‌کارت و پوشش وای‌فای مناسب منزل و دفتر کار.','مودم روتر 4G LTE بی‌سیم با پشتیبانی سیم‌کارت',5300000,4550000,6,'/static/images/prod-router-a.jpg','[]','[{\"group\":\"ارتباطات\",\"key\":\"ثبل3قل\",\"value\":\"45ع5ا5\"}]','','','',4,'inactive',0,29,'[]',NULL,'2026-07-04 23:12:19','2026-08-03 23:17:59',NULL),
(2,'نوار چسب برق VTOOLS','نوار-چسب-برق-وی-تولز-10-یارد','VTL-ET-10YD-10PK',32,7,'نوار چسب برق عایق وی تولز (Vtools) با طول ۱۰ یارد یک محصول کاربردی و مقرون‌به‌صرفه از برند معتبر وی تولز است که به طور خاص برای استفاده‌های عمومی در برق‌کاری و عایق‌سازی طراحی شده است. این محصول از جنس PVC با کیفیت قابل قبول ساخته شده است.\n\nاین نوار چسب با ابعاد استاندارد ۰.۱۳ میلی‌متر ضخامت و ۱۹ میلی‌متر عرض، پوشش مناسبی برای انواع سیم و کابل فراهم می‌کند. طول ۱۰ یارد (حدود ۹ متر) آن نیز برای انجام چندین نوبت کار و استفاده‌های روزمره، انتخابی اقتصادی محسوب می‌شود. چسبندگی یکنواخت آن باعث می‌شود به راحتی روی سیم پیچیده شود و عایق‌بندی مطمئنی ایجاد کند. همچنین از استحکام کافی برخوردار است و در استفاده معمول در برابر پارگی مقاومت خوبی دارد.\n\nجنس پی‌وی‌سی (PVC) این نوار چسب، انعطاف‌پذیری خوبی به آن بخشیده و آن را در برابر حرارت تا حدود ۸۰ درجه سانتی‌گراد مقاوم کرده است، که برای مصارف عادی برق‌کاری کافی و مناسب است.','',65000,62000,291,'/static/uploads/up-1784442498188-j4yto1.webp','[\"/static/uploads/up-1784442517938-9zanfr.webp\",\"/static/uploads/up-1784442530784-izjbcp.webp\",\"/static/uploads/up-1784442544331-kd97zf.webp\",\"/static/uploads/up-1784442558082-ai197w.jpg\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"وی تولز\"},{\"group\":\"مشخصات پایه\",\"key\":\"کشور سازنده\",\"value\":\"چین\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع محصول\",\"value\":\"نوار چسب برق عایق\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس\",\"value\":\"PVC\"},{\"group\":\"ابعاد\",\"key\":\"طول\",\"value\":\"حدود ۹ متر\"},{\"group\":\"ابعاد\",\"key\":\"عرض\",\"value\":\"۱۹ میلی‌متر\"},{\"group\":\"ابعاد\",\"key\":\"ضخامت\",\"value\":\"۰.۱۳ میلی‌متر\"},{\"group\":\"بسته‌بندی\",\"key\":\"تعداد در کارتن\",\"value\":\"۵۰۰ عدد\"},{\"group\":\"بسته‌بندی\",\"key\":\"نوع بسته‌بندی خرد\",\"value\":\"بسته‌های ۱۰ عددی\"}]','خرید نوار چسب برق وی تولز Vtools 10 یارد | قیمت چسب برق نسوز','نوار چسب برق عایق PVC برند وی تولز (Vtools) با طول ۱۰ یارد، ضخامت ۰.۱۳ میلی‌متر و پهنای ۱۹ میلی‌متر. مناسب برای عایق‌کاری و دسته‌بندی سیم و کابل. دارای چسبندگی یکنواخت، مقاوم در برابر حرارت و گارانتی اصالت کالا. ارسال سریع به سراسر ایران.\n\n','نوار چسب برق وی تولز، چسب برق Vtools، نوار عایق PVC، چسب برق ۱۰ یارد، چسب برق نسوز، لوازم برق کشی، نوار چسب مشکی برق',0,'active',1,290,'[\"◉ جنس PVC باکیفیت – انعطاف‌پذیر و مقاوم در برابر پارگی در استفاده معمول\",\"◉ ضخامت ۰.۱۳ میلی‌متر – با چسبندگی یکنواخت و پیچش آسان روی سیم\",\"◉ قابلیت تحمل دما تا ۸۰ درجه سانتی‌گراد – مقاوم در برابر حرارت\",\"◉ تنوع رنگ عالی – در رنگ‌های مشکی، سبز، قرمز، زرد، آبی و سفید\",\"◉ ساخت چین – با رعایت استانداردهای اولیه عایق‌کاری\",\"◉ بسته‌بندی مناسب – بسته ۱۰ عددی برای مصارف خانگی، فروشگاهی و کارگاهی\"]','','2026-07-04 23:12:19','2026-10-01 16:42:04',NULL),
(6,'مودم روتر 4G LTE نتربیت مدل NW-431F','neterbit-nw431f','NET-NW431F-001',26,3,'مودم روتر ۴G LTE نتربیت مدل NW-431F یک راه‌حل کامل و مقرون‌به‌صرفه برای برقراری اینترنت پرسرعت در مناطقی است که دسترسی به ADSL، VDSL یا فیبر نوری محدود است یا به عنوان یک اتصال پشتیبان در کنار خطوط ثابت عمل می‌کند. این دستگاه با استفاده از یک سیم‌کارت ۴G (همراه اول، ایرانسل، رایتل یا شاتل موبایل) اینترنت موبایل را به یک شبکه وای‌فای قدرتمند با پوشش گسترده و پورت‌های سیمی تبدیل می‌کند.\n\nبرند نتربیت (Neterbit) با پشتوانه دانش متخصصان و محققان تایوانی و بر اساس لایسنس فعالیت می‌کند. این برند با ارائه گارانتی ۳۶ ماهه آونگ، اطمینان خاطر بیشتری را برای خریداران فراهم می‌کند.\n\n','مودم روتر ۴G LTE نتربیت مدل NW-431F یک دستگاه جمع‌وجور و کاربردی برای تبدیل اینترنت سیم‌کارت به وای‌فای و پورت‌های سیمی است. این مودم با سرعت دانلود تا ۱۵۰ مگابیت بر ثانیه، وای‌فای N300 با ۴ آنتن خارجی، ۴ پورت LAN و پورت تلفن (VoIP)، انتخابی مناسب برای منازل، دفاتر کوچک و مناطقی با دسترسی محدود به ADSL یا فیبر نوری می‌باشد.',6800000,6300000,15,'/static/uploads/up-1784557826095-wpm4dt.webp','[\"/static/uploads/up-1784557854094-zp5qxl.webp\",\"/static/uploads/up-1784557881757-75jnwy.webp\",\"/static/uploads/up-1784557884430-7y0sqr.webp\"]','[{\"group\":\"شبکه موبایل\",\"key\":\"نسل شبکه\",\"value\":\"۴G LTE / ۳G / ۲G\"},{\"group\":\"شبکه موبایل\",\"key\":\"سرعت دانلود (LTE)\",\"value\":\"تا ۱۵۰ مگابیت بر ثانیه\"},{\"group\":\"شبکه موبایل\",\"key\":\"سرعت آپلود (LTE)\",\"value\":\"تا ۵۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت LAN\",\"value\":\"۴ عدد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"شیار سیم‌کارت\",\"value\":\"۱ عدد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"دکمه‌ها\",\"value\":\"Reset، Power\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"آنتن‌ها\",\"value\":\"۴ عدد خارجی\"},{\"group\":\"برق و محیطی\",\"key\":\"دمای کاری\",\"value\":\"۰ تا ۵۰ درجه سانتی‌گراد\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"۳۶ ماه گارانتی آونگ\"}]','خرید مودم ۴G LTE نتربیت NW-431F | قیمت روتر سیمکارتی N300','مودم روتر 4G LTE نتربیت مدل NW-431F با سرعت دانلود ۱۵۰ مگابیت، وای‌فای N300، ۴ آنتن خارجی و گارانتی ۳۶ ماهه آونگ. مناسب برای منزل، اداره و اینترنت پشتیبان. ارسال سریع.\n\n','مودم ۴G، نتربیت NW-431F، روتر LTE، مودم سیمکارتی، مودم همراه اول، مودم ایرانسل، مودم ۴G نتربیت، خرید مودم ۴G، Neterbit NW-431F',3,'active',1,40,'[\"◉ ۴G LTE با سرعت دانلود ۱۵۰ مگابیت بر ثانیه\",\"◉ ۴ پورت LAN ۱۰/۱۰۰ مگابیت برای اتصال سیمی\",\"◉ پشتیبانی از سیم‌کارت ایرانسل، همراه اول، رایتل، شاتل موبایل\",\"◉ نصب Plug and Play – بدون نیاز به تنظیمات خاص\",\"◉ مدیریت آسان از طریق وب‌اینترفیس با قابلیت مشاهده پیامک‌ها\",\"◉ گارانتی ۳۶ ماهه آونگ\"]','','2026-07-04 23:12:19','2026-10-01 16:42:36',NULL),
(13,'پچ پنل 24 پورت لگراند Cat6 UTP وارداتی','legrand-24-port-cat6-utp-patch-panel','LG-PP24B',31,1,'یک راه‌حل حرفه‌ای و استاندارد برای سازماندهی اتصالات شبکه در رک‌های ۱۹ اینچی است. این محصول وارداتی و اورجینال با ۲۴ کیستون Cat6 UTP از پیش نصب شده (لوده شده)، مکانیزم Quick-Fixing برای نصب بدون پیچ، کاست‌های ۶ پورتی قابل جدا شدن و مدیریت کابل در پشت پنل，انتخابی ایده‌آل برای دیتاسنترها، شبکه‌های سازمانی و پروژه‌های کابل‌کشی ساختاریافته می‌باشد.\n\n','پچ پنل ۲۴ پورت لگراند Cat6 UTP مدل 033560، یک راه‌حل حرفه‌ای و استاندارد برای سازماندهی اتصالات شبکه در رک‌های ۱۹ اینچی است. این محصول وارداتی و اورجینال با ۲۴ کیستون Cat6 UTP از پیش نصب شده (لوده شده)، مکانیزم Quick-Fixing برای نصب بدون پیچ، کاست‌های ۶ پورتی قابل جدا شدن و مدیریت کابل در پشت پنل，انتخابی ایده‌آل برای دیتاسنترها، شبکه‌های سازمانی و پروژه‌های کابل‌کشی ساختاریافته می‌باشد.',5300000,5200000,10,'/static/uploads/up-1785393657704-xqxzln.webp','[\"/static/uploads/up-1783844827714-63b7f0.webp\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"کشور سازنده\",\"value\":\"فرانسه (وارداتی و اورجینال)\"},{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"لگراند (Legrand)\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع محصول\",\"value\":\"پچ پنل مسی از پیش تجهیز شده (Loaded)\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع\",\"value\":\"UTP (بدون شیلد)UTP (بدون شیلد)\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد پورت\",\"value\":\"۲۴ عدد RJ45 8(8)\"},{\"group\":\"مشخصات پایه\",\"key\":\"فضای مورد نیاز رک\",\"value\":\"۱ یونیت (1U) – ارتفاع ۴۳.۸۵ میلی‌متر\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"عرض\",\"value\":\"۴۸۲.۵ میلی‌متر (۱۹ اینچ)\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"ارتفاع\",\"value\":\"۴۳.۸۵ میلی‌متر\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"عمق\",\"value\":\"۳۲۱.۷ میلی‌متر\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"رنگ\",\"value\":\"مشکی\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"جنس پنل/فریم\",\"value\":\"فلز\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"۱ گیگابیت بر ثانیه (۱۰/۱۰۰/۱۰۰۰BASE-T)\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"دمای کاری\",\"value\":\"۲۵- تا ۷۰+ درجه سانتی‌گراد\"},{\"group\":\"نصب و نگهداری\",\"key\":\"روش نصب روی رک\",\"value\":\"Quick-Fixing (مکانیزم قفلی بدون پیچ)\"},{\"group\":\"محتویات جعبه\",\"key\":\"محتویات\",\"value\":\"فریم فلزی پنل با ۴ کاست ۶ پورتی (۲۴ کیستون)\"},{\"group\":\"محتویات جعبه\",\"key\":\"راهنما\",\"value\":\"دفترچه راهنمای نصب\"}]','خرید پچ پنل 24 پورت لگراند Cat6 UTP | قیمت 033560 اورجینال','پچ پنل ۲۴ پورت لگراند Cat6 UTP مدل 033560 با ۲۴ کیستون اورجینال، مکانیزم Quick-Fix و مدیریت کابل. مناسب برای شبکه‌های سازمانی و دیتاسنتر. گارانتی اصالت و ارسال سریع.\n\n','پچ پنل لگراند ۲۴ پورت، پچ پنل Cat6 UTP، پچ پنل ۲۴ پورت لگراند مدل 033560، پچ پنل لگراند LCS³، تجهیزات شبکه پسیو، پچ پنل کیستونی رک، Legrand 24 Port Cat6 UTP Patch Panel',0,'active',0,76,'[\"◉ ۲۴ پورت Cat6 UTP – سرعت ۱ گیگابیت، پهنای باند ۲۵۰ مگاهرتز\",\"◉ نصب Quick-Fix بدون پیچ – نصب خودکار روی رک با کلیپس‌های قفلی\",\"◉ مدیریت کابل یکپارچه – دارای ریل و گیره نگهدارنده در پشت پنل\",\"◉ کاست‌های ۶ پورتی قابل جدا شدن – عیب‌یابی و تعویض آسان بدون خارج کردن پنل از رک\",\"◉ برند فرانسه لگراند – اورجینال با تست فلوک و گارانتی اصالت\"]','','2026-07-04 23:12:19','2026-10-01 16:42:04',NULL),
(14,'کابل شبکه Cat6 UTP تمام مس لگراند مغزی 0.40','legrand-cat6-cable','LEG-CAT6-UTP-040-305',22,1,'کابل شبکه CAT6 UTP لگراند با مغزی تمام مس و قطر ۰.۴۰ میلی‌متر، یکی از پرفروش‌ترین و پرکاربردترین کابل‌های شبکه در بازار ایران است. این کابل توسط شرکت معتبر فرانسوی لگراند (Legrand) تولید شده و برای ارسال و دریافت اطلاعات و انتقال داده‌ها بدون افت کیفیت طراحی شده است.\n\nکابل شبکه لگراند CAT6 UTP با مغزی ۰.۴۰ از ۴ جفت سیم تابیده (۴ Pair Twisted) ساخته شده است. هسته این کابل از مس خالص (CCC) ساخته شده تا اطلاعات را با بالاترین کیفیت انتقال دهد. این کابل در متراژ ۱۰۰ متری و ۳۰۵ متری به بازار عرضه شده است.','کابل شبکه CAT6 UTP لگراند با مغزی تمام مس (CCC) و قطر ۰.۴۰ میلی‌متر، یک کابل استاندارد و باکیفیت برای شبکه‌های ساختاریافته است. این کابل با پشتیبانی از سرعت انتقال داده تا ۱ گیگابیت بر ثانیه و پهنای باند ۲۵۰ مگاهرتز، برای کابل‌کشی افقی در ساختمان‌های مسکونی، اداری و تجاری ایده‌آل می‌باشد. روکش PVC مقاوم، ساختار ۴ زوج به‌تابیده و بسته‌بندی حلقه ۳۰۵ متری، این محصول را به یکی از پرفروش‌ترین کابل‌های شبکه در بازار ایران تبدیل کرده است.',16165000,16775000,150,'/static/uploads/up-1785394527195-zvkp43.webp','[\"/static/uploads/up-1784376979530-lyep3v.jpg\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"لگراند\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"CAT6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"UTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۴۰ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد زوج\",\"value\":\"۴ زوج (۸ رشته)\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس روکش\",\"value\":\"PVC\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"۱۰/۱۰۰/۱۰۰۰ مگابیت بر ثانیه\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"پهنای باند\",\"value\":\"۲۵۰ مگاهرتز\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"حداکثر فاصله انتقال\",\"value\":\"۱۰۰ متر\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"تست فلوک\",\"value\":\"ندارد\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"نوع بسته‌بندی\",\"value\":\"کارتن\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"گارانتی اصالت و سلامت فیزیکی کالا\"}]','خرید کابل شبکه CAT6 UTP لگراند تمام مس ۰.۴۰ | قیمت حلقه 305 متری','کابل شبکه CAT6 UTP لگراند با مغزی تمام مس ۰.۴۰ میلی‌متر، پهنای باند ۲۵۰ مگاهرتز و سرعت ۱ گیگابیت بر ثانیه. مناسب برای کابل‌کشی شبکه‌های داخلی. حلقه ۳۰۵ متری با روکش PVC. ارسال سریع و گارانتی اصالت.\n\n','کابل شبکه لگراند، کابل CAT6 UTP، کابل تمام مس لگراند، کابل شبکه ۰.۴۰ لگراند، کابل شبکه لگراند ۳۰۵ متری، قیمت کابل لگراند Cat6، Legrand Cat6 UTP cable',0,'active',0,142,'[\"◉ استاندارد CAT6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ مغزی تمام مس (CCC) – با قطر ۰.۴۰ میلی‌متر، رسانایی عالی و بدون افت سیگنال\",\"◉ ساختار UTP – بدون شیلد، مناسب برای محیط‌های داخلی و اداری\",\"◉ ۴ زوج به‌تابیده – کاهش نویز Crosstalk با گام پیچش متفاوت\",\"◉ طول ۳۰۵ متر در هر حلقه – بسته‌بندی استاندارد کارتن\",\"◉ ۴ زوج به‌تابیده – کاهش نویز Crosstalk با گام پیچش متفاوت\"]','','2026-07-04 23:12:19','2026-10-01 16:42:04',NULL),
(15,'روتر تندا N300 مدل N301','tenda-n301','TD-N301',27,6,'روتر بی‌سیم N300 تندا مدل N301 یک دستگاه مقرون‌به‌صرفه و کاربردی از برند معتبر تندا (Tenda) است که برای تأمین اینترنت بی‌سیم در منازل مسکونی، دفاتر کوچک، کافی‌شاپ‌ها و محیط‌های آموزشی طراحی شده است. این روتر با بهره‌گیری از استاندارد ۸۰۲.۱۱n و ۲ آنتن خارجی ۵dBi، پوشش وای‌فای مناسبی را برای فضاهای متوسط (تا حدود ۱۰۰ متر مربع) فراهم می‌کند.\n\n','روتر بی‌سیم N300 تندا مدل N301 با دو آنتن ۵dBi، سرعت ۳۰۰ مگابیت بر ثانیه و قابلیت‌های متنوع مانند کنترل والدین، شبکه میهمان و حالت‌های کاری چندگانه (روتر، اکسس پوینت، ریپیتر و WISP)، یک انتخاب مقرون‌به‌صرفه و کاربردی برای منازل و دفاتر کوچک است. نصب آسان با WPS و رابط کاربری ساده، راه‌اندازی این روتر را در کمترین زمان ممکن می‌سازد.',2950000,2950000,18,'/static/uploads/up-1785394789095-m5t0c6.webp','[\"/static/uploads/up-1784443667925-b3zf6x.jpg\"]','[{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت WAN\",\"value\":\"۱ عدد  ۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت LAN\",\"value\":\"۳ عدد  ۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"دکمه‌ها\",\"value\":\"Reset/WPS\"},{\"group\":\"فیزیکی\",\"key\":\"ابعاد (طول×عرض×ارتفاع)\",\"value\":\"۱۲۷.۴ × ۹۰.۵ × ۲۶ میلی‌متر\"},{\"group\":\"فیزیکی\",\"key\":\"وزن\",\"value\":\"حدود ۲۰۰ گرم\"},{\"group\":\"فیزیکی\",\"key\":\"منبع تغذیه\",\"value\":\"۹ ولت / ۰.۶ آمپر\"}]','خرید روتر بی‌سیم N300 تندا N301 | قیمت و مشخصات Tenda','روتر بی‌سیم N300 تندا مدل N301 با دو آنتن 5dBi، سرعت 300 مگابیت بر ثانیه و قابلیت کنترل والدین. مناسب برای منزل و اداره. دارای گارانتی معتبر و ارسال سریع.\n\n','روتر تندا N301، روتر بی سیم N300، Tenda N301، روتر وای فای تندا، روتر خانگی تندا، قیمت روتر تندا N301',1,'active',0,138,'[\"◉ سرعت ۳۰۰ مگابیت بر ثانیه – استاندارد ۸۰۲.۱۱n در باند ۲.۴ گیگاهرتز\",\"◉ ۲ آنتن خارجی ۵dBi – پوشش مناسب برای فضاهای تا ۱۰۰ متر مربع\",\"◉ ۳ پورت LAN + ۱ پورت WAN – اتصال سیمی با سرعت ۱۰/۱۰۰ مگابیت\",\"◉ نصب آسان با دکمه WPS – اتصال سریع و امن دستگاه‌ها\",\"◉ شبکه میهمان (Guest Network) – دسترسی جداگانه برای مهمانان\",\"◉ ابعاد جمع‌وجور – ۱۲۷.۴×۹۰.۵×۲۶ میلی‌متر\"]','گارانتی 36 ماهه آونگ','2026-07-04 23:12:19','2026-10-01 16:42:04',NULL),
(28,'مودم دی لینک مدل DWR M920','d-link-dwr-m920-4g-lte-router','',26,3,'مودم روتر ۴G LTE دی لینک مدل DWR-M920 یک راه‌حل کامل و مقرون‌به‌صرفه برای برقراری اینترنت پرسرعت در مناطقی است که دسترسی به ADSL، VDSL یا فیبر نوری محدود است یا به عنوان یک اتصال پشتیبان (Failover) در کنار خطوط ثابت عمل می‌کند. این دستگاه با استفاده از یک سیم‌کارت ۴G (همراه اول، ایرانسل، رایتل) اینترنت موبایل را به یک شبکه وای‌فای قدرتمند با پوشش مناسب و پورت‌های سیمی تبدیل می‌کند.\n\n','مودم روتر ۴G LTE دی لینک مدل DWR-M920 یک راه‌حل مقرون‌به‌صرفه و کارآمد برای تبدیل اینترنت سیم‌کارت به وای‌فای و پورت‌های سیمی است. این دستگاه با سرعت دانلود تا ۱۵۰ مگابیت بر ثانیه، وای‌فای N300 با ۲ آنتن ۵dBi و قابلیت Failover (اتصال پشتیبان)، گزینه‌ای مناسب برای منازل، دفاتر کوچک و مناطقی با دسترسی محدود به ADSL یا فیبر نوری محسوب می‌شود',8500000,8300000,9,'/static/uploads/up-1785395154696-liepvo.webp','[\"/static/uploads/up-1783842008924-w8f55j.webp\",\"/static/uploads/up-1783842012218-mt6os7.webp\"]','[{\"group\":\"شبکه موبایل\",\"key\":\"نسل شبکه\",\"value\":\"۴G LTE Cat4 / ۳G / ۲G\"},{\"group\":\"شبکه موبایل\",\"key\":\"سرعت دانلود (LTE)\",\"value\":\"تا ۱۵۰ مگابیت بر ثانیه\"},{\"group\":\"شبکه موبایل\",\"key\":\"سرعت آپلود (LTE)\",\"value\":\"تا ۵۰ مگابیت بر ثانیه\"},{\"group\":\"شبکه موبایل\",\"key\":\"نوع سیم‌کارت\",\"value\":\"استاندارد (۲FF)\"},{\"group\":\"شبکه بی‌سیم\",\"key\":\"سرعت وای‌فای\",\"value\":\"تا ۳۰۰ مگابیت بر ثانیه (N300)\"},{\"group\":\"شبکه بی‌سیم\",\"key\":\"تعداد آنتن‌های خارجی (مجموع)\",\"value\":\"۴ عدد (۲ عدد LTE + ۲ عدد وای‌فای)\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت WAN\",\"value\":\"۱ عدد RJ45 ۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت LAN\",\"value\":\"۳ عدد RJ45 ۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت USB\",\"value\":\"ندارد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"دکمه‌ها\",\"value\":\"Power Switch، WPS، Reset\"},{\"group\":\"نرم‌افزار و مدیریت\",\"key\":\"آدرس مدیریت\",\"value\":\"۱۹۲.۱۶۸.۰.۱