(54,'بلانک پنل 1 یونیت ','بلانک-پنل-1-یونیت','AMA-BP-1U-001',29,9,'بلانک پنل ۱ یونیت (1U رک) یک قطعه ساده و در عین حال حیاتی در تجهیزات پسیو شبکه است. این صفحه پوشش فلزی، فضای خالی یا استفاده نشده در یک رک ۱۹ اینچی را می‌پوشاند و به عنوان یکی از متعلقات اصلی رک شناخته می‌شود.\n\nامروزه در دیتاسنترها و اتاق‌های سرور، استفاده از بلانک پنل یک الزام فنی محسوب می‌شود. این تجهیزات به شکل قابل توجهی به مدیریت دمای داخل رک کمک می‌کنند. با مسدود کردن فضاهای خالی، مانع از چرخش مجدد هوای گرم خارج شده از تجهیزات به سمت جلوی رک می‌شوند و هوای سرد را به مسیر درست هدایت می‌کنند.','بلانک پنل ۱ یونیت (1U) یک صفحه فلزی استاندارد ۱۹ اینچی است که برای پوشاندن فضاهای خالی (یونیت‌های استفاده نشده) در رک‌های شبکه و سرور به کار می‌رود. این صفحه با ایجاد نظم ظاهری، بهبود جریان هوای داخل رک، جلوگیری از نفوذ گرد و غبار و افزایش امنیت تجهیزات، نقشی حیاتی در بهینه‌سازی و حفاظت از زیرساخت شبکه ایفا می‌کند',150000,143000,50,'/static/uploads/up-1784355006596-vzlcg8.webp','[]','[{\"group\":\"مشخصات اصلی\",\"key\":\"نوع محصول\",\"value\":\"بلانک پنل\"},{\"group\":\"مشخصات اصلی\",\"key\":\"تعداد یونیت\",\"value\":\"۱ یونیت\"},{\"group\":\"مشخصات اصلی\",\"key\":\"ارتفاع فیزیکی\",\"value\":\"۴۴.۴۵ میلی‌متر\"},{\"group\":\"مشخصات اصلی\",\"key\":\"عرض استاندارد\",\"value\":\"۴۸۲.۶ میلی‌متر\"},{\"group\":\"جنس و ساختار\",\"key\":\"رنگ\",\"value\":\"مشکی با پوشش رنگ پودری الکترواستاتیک\"},{\"group\":\"جنس و ساختار\",\"key\":\"ضخامت ورق\",\"value\":\"معمولاً ۰.۷ تا ۱ میلی‌متر\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"گارانتی اصالت و سلامت فیزیکی کالا\"}]','خرید بلانک پنل ۱ یونیت رک | قیمت صفحه پوشش 1U','بلانک پنل 1U رک شبکه و سرور با استاندارد ۱۹ اینچ، جنس فلزی با پوشش رنگ پودری مشکی، مناسب برای پوشاندن فضای خالی، بهبود جریان هوا، جلوگیری از گرد و غبار و افزایش امنیت تجهیزات در رک.\n\n','بلانک پنل 1U، بلنک پنل یک یونیت، blank panel 1U، صفحه پوشش رک، متعلقات رک، تجهیزات پسیو شبکه، رک شبکه',0,'active',0,0,'[\"◉ استاندارد ۱۹ اینچ – سازگار با تمام رک‌های شبکه و سرور\",\"◉ ارتفاع ۱ یونیت (1U) – پوشش فضای خالی یک واحدی در رک\",\"◉ بدنه فلزی با پوشش رنگ پودری الکترواستاتیک مشکی – مقاوم در برابر خش و خوردگی\",\"◉ بهبود جریان هوا – افزایش راندمان خنک‌کاری و کاهش مصرف انرژی\",\"◉ جلوگیری از نفوذ گرد و غبار – محافظت از تجهیزات حساس\",\"◉ ظاهر یکدست و حرفه‌ای – نظم‌دهی بصری به رک\",\"◉ گارانتی اصالت و سلامت فیزیکی\"]',NULL,'2026-07-18 06:15:52','2026-08-03 23:17:59',NULL),
(55,'بلانک پنل 2 یونیت ','بلانک-پنل-2-یونیت','AMA-BP-2U-001',29,9,'بلانک پنل ۲ یونیت (2U رک) یک قطعه ساده و در عین حال حیاتی در تجهیزات پسیو شبکه است. این صفحه پوشش فلزی، فضای خالی یا استفاده نشده به ارتفاع ۲ یونیت (حدود ۹ سانتی‌متر) در یک رک ۱۹ اینچی را می‌پوشاند و به عنوان یکی از متعلقات اصلی رک شناخته می‌شود.\n\nامروزه در دیتاسنترها و اتاق‌های سرور، استفاده از بلانک پنل یک الزام فنی محسوب می‌شود. این تجهیزات به شکل قابل توجهی به مدیریت دمای داخل رک کمک می‌کنند. با مسدود کردن فضاهای خالی، مانع از چرخش مجدد هوای گرم خارج شده از تجهیزات به سمت جلوی رک می‌شوند و هوای سرد را به مسیر درست (از جلوی تجهیزات به داخل و سپس خروج از پشت) هدایت می‌کنند.','بلانک پنل ۲ یونیت (2U) یک صفحه فلزی استاندارد ۱۹ اینچی است که برای پوشاندن فضاهای خالی (یونیت‌های استفاده نشده) در رک‌های شبکه و سرور به کار می‌رود. این صفحه با ایجاد نظم ظاهری، بهبود جریان هوای داخل رک، جلوگیری از نفوذ گرد و غبار و افزایش امنیت تجهیزات، نقشی حیاتی در بهینه‌سازی و حفاظت از زیرساخت شبکه ایفا می‌کند.',240000,228000,50,'/static/uploads/up-1784355427447-aa0mze.webp','[]','[{\"group\":\"مشخصات اصلی\",\"key\":\"نوع محصول\",\"value\":\"بلانک پنل\"},{\"group\":\"مشخصات اصلی\",\"key\":\"تعداد یونیت\",\"value\":\"۲ یونیت\"},{\"group\":\"مشخصات اصلی\",\"key\":\"ارتفاع فیزیکی\",\"value\":\"۸۸.۹ میلی‌متر\"},{\"group\":\"مشخصات اصلی\",\"key\":\"عرض استاندارد\",\"value\":\"۱۹ اینچ\"},{\"group\":\"جنس و ساختار\",\"key\":\"جنس بدنه\",\"value\":\"ورق فولادی\"},{\"group\":\"جنس و ساختار\",\"key\":\"رنگ\",\"value\":\"مشکی با پوشش رنگ پودری الکترواستاتیک\"},{\"group\":\"جنس و ساختار\",\"key\":\"ضخامت ورق\",\"value\":\"معمولاً ۰.۷ تا ۱ میلی‌متر\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"گارانتی اصالت و سلامت فیزیکی کالا\"}]','خرید بلانک پنل ۲ یونیت رک | قیمت صفحه پوشش 2U','بلانک پنل 2U رک شبکه و سرور با استاندارد ۱۹ اینچ، جنس فلزی با پوشش رنگ پودری مشکی، مناسب برای پوشاندن فضای خالی، بهبود جریان هوا، جلوگیری از گرد و غبار و افزایش امنیت تجهیزات در رک.\n\n','بلانک پنل 2U، بلنک پنل دو یونیت، blank panel 2U، صفحه پوشش