(66,'سوییچ 5 پورت نتربیت مدل NGS-1005A','سوییچ-5-پورت-نتربیت-مدل-ngs-1005a','NET-NGS1005A-001',20,3,'سوئیچ شبکه ۵ پورت گیگابیتی نتربیت مدل NGS-1005A یک دستگاه غیرمدیریتی، جمع‌وجور و کارآمد از برند معتبر نتربیت (Neterbit) است که برای افزایش پورت‌های شبکه در منازل، دفاتر کوچک (SOHO) و محیط‌های کاری طراحی شده است. این سوئیچ با ۵ پورت ۱۰/۱۰۰/۱۰۰۰ مگابیت بر ثانیه، امکان اتصال همزمان چندین دستگاه مانند کامپیوتر، لپ‌تاپ، پرینتر، دوربین مداربسته IP، تلویزیون 4K هوشمند و کنسول بازی را با سرعت گیگابیتی فراهم می‌کند.\n\nبرند نتربیت (Neterbit) با پشتوانه دانش متخصصان و محققان تایوانی و بر اساس لایسنس فعالیت می‌کند و محصولات خود را از سال ۱۳۹۸ به بازار عرضه کرده است. این برند با ارائه گارانتی ۳۶ ماهه آونگ، اطمینان خاطر بیشتری را برای خریداران فراهم می‌کند.','سوئیچ ۵ پورت گیگابیتی نتربیت مدل NGS-1005A یک دستگاه غیرمدیریتی و جمع‌وجور با بدنه فلزی مقاوم است که برای افزایش پورت‌های شبکه در منازل، دفاتر کوچک و محیط‌های کاری طراحی شده است. این سوئیچ با ۵ پورت ۱۰/۱۰۰/۱۰۰۰ مگابیت بر ثانیه، ظرفیت سوئیچینگ ۱۰ گیگابیت بر ثانیه و طراحی بدون فن، نصب آسان و عملکردی بی‌صدا و پرسرعت را ارائه می‌دهد.',1550000,NULL,10,'/static/uploads/up-1784469111051-5yse2x.webp','[\"/static/uploads/up-1784469164892-r2pdxe.webp\"]','[{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"تعداد پورت\",\"value\":\"۵ عدد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"سرعت پورت\",\"value\":\"۱۰/۱۰۰/۱۰۰۰ مگابیت بر ثانیه (گیگابیتی)\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت SFP\",\"value\":\"ندارد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت Uplink\",\"value\":\"ندارد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پشتیبانی از PoE\",\"value\":\"ندارد\"},{\"group\":\"عملکرد شبکه\",\"key\":\"نوع سوئیچ\",\"value\":\"غیرمدیریتی\"},{\"group\":\"فیزیکی و برق\",\"key\":\"جنس بدنه\",\"value\":\"فلزی\"},{\"group\":\"فیزیکی و برق\",\"key\":\"موقعیت نصب\",\"value\":\"رومیزی\"},{\"group\":\"فیزیکی و برق\",\"key\":\"وزن\",\"value\":\"۲۰۰ گرم\"},{\"group\":\"فیزیکی و برق\",\"key\":\"منبع تغذیه\",\"value\":\"آداپتور خارجی ۵ ولت DC / ۱ آمپر\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"۳۶ ماه (۳ سال) گارانتی شرکت آونگ\"}]','خرید سوئیچ 5 پورت گیگابیتی نتربیت NGS-1005A | قیمت Neterbit','سوئیچ ۵ پورت گیگابیتی نتربیت مدل NGS-1005A با سرعت ۱۰/۱۰۰/۱۰۰۰ مگابیت، ظرفیت سوئیچینگ ۱۰ گیگابیت، بدنه فلزی و گارانتی ۳۶ ماهه آونگ. مناسب برای منزل و اداره. نصب Plug and Play و ارسال سریع.\n\n','سوئیچ نتربیت NGS-1005A، سوئیچ ۵ پورت نتربیت، Neterbit NGS-1005A، سوئیچ شبکه ۵ پورت گیگابیتی، سوئیچ دسکتاپ نتربیت، سوئیچ گیگابیتی ارزان، سوئیچ بدون فن، گارانتی آونگ',0,'active',0,6,'[\"۵ پورت ۱۰/۱۰۰/۱۰۰۰ مگابیت بر ثانیه – سرعت گیگابیتی برای اتصال همزمان چندین دستگاه\",\"ظرفیت سوئیچینگ ۱۰ گیگابیت بر ثانیه – پهنای باند کافی بدون افت کیفیت\",\"بدنه فلزی مقاوم – دوام بالا و دفع بهتر حرارت\",\"طراحی بدون فن و کاملاً بی‌صدا – مناسب برای محیط‌های آرام\",\"نصب Plug and Play – بدون نیاز به تنظیمات\",\"گارانتی ۳۶ ماهه آونگ – تضمین کیفیت و اصالت\"]','گارانتی 36 ماهه آونگ','2026-07-19 13:58:21','2026-10-01 15:02:07',NULL),
(67,'سوییچ 5 پورت نتربیت مدل NES-1005E-C','سوییچ-5-پورت-نتربیت-مدل-nes-1005e-c','NET-NES1005EC-001',20,3,'سوئیچ شبکه ۵ پورت Fast Ethernet نتربیت مدل NES-1005E-C یک دستگاه غیرمدیریتی، جمع‌وجور و اقتصادی از برند معتبر نتربیت (Neterbit) است که برای افزایش پورت‌های شبکه در منازل، دفاتر کوچک (SOHO) و محیط‌های کاری طراحی شده است. این سوئیچ با ۵ پورت ۱۰/۱۰۰ مگابیت بر ثانیه، امکان اتصال همزمان چندین دستگاه مانند کامپیوتر، لپ‌تاپ، پرینتر، دوربین مداربسته IP و کنسول بازی را فراهم می‌کند.\n\nبرند نتربیت (Neterbit) با پشتوانه دانش متخصصان و محققان تایوانی و بر اساس لایسنس فعالیت می‌کند. این برند با ارائه گارانتی ۳۶ ماهه آونگ، اطمینان خاطر بیشتری را برای خریداران فراهم می‌کند.\n\n','سوئیچ شبکه ۵ پورت ۱۰/۱۰۰ مگابیت نتربیت مدل NES-1005E-C یک دستگاه غیرمدیریتی و جمع‌وجور است که برای افزایش پورت‌های شبکه در منازل، دفاتر کوچک و محیط‌های کاری طراحی شده است. این سوئیچ با ۵ پورت Fast Ethernet، ظرفیت سوئیچینگ ۱ گیگابیت بر ثانیه، طراحی بدون فن و گارانتی ۳۶ ماهه آونگ، نصب آسان و عملکردی بی‌صدا و اقتصادی را ارائه می‌دهد.',1500000,NULL,0,'/static/uploads/up-1784469606506-htp1n2.jpg','[]','[{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"تعداد پورت\",\"value\":\"۵ عدد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"سرعت پورت\",\"value\":\"۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت SFP\",\"value\":\"ندارد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت Uplink\",\"value\":\"ندارد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پشتیبانی از PoE\",\"value\":\"ندارد\"},{\"group\":\"عملکرد شبکه\",\"key\":\"نوع سوئیچ\",\"value\":\"غیرمدیریتی\"},{\"group\":\"فیزیکی و برق\",\"key\":\"جنس بدنه\",\"value\":\"پلاستیکی\"},{\"group\":\"فیزیکی و برق\",\"key\":\"موقعیت نصب\",\"value\":\"رومیزی\"},{\"group\":\"فیزیکی و برق\",\"key\":\"وزن\",\"value\":\"۵۰ گرم\"},{\"group\":\"فیزیکی و برق\",\"key\":\"منبع تغذیه\",\"value\":\"آداپتور خارجی ۵ ولت\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"۳۶ ماه (۳ سال) گارانتی شرکت آونگ\"}]','خرید سوئیچ 5 پورت نتربیت NES-1005E-C | قیمت Neterbit','سوئیچ ۵ پورت نتربیت مدل NES-1005E-C با سرعت ۱۰/۱۰۰ مگابیت، ظرفیت سوئیچینگ ۱ گیگابیت، بدنه پلاستیکی و گارانتی ۳۶ ماهه آونگ. مناسب برای منزل و اداره. نصب Plug and Play و ارسال سریع.\n\n','سوئیچ نتربیت NES-1005E-C، سوئیچ ۵ پورت نتربیت، Neterbit NES-1005E-C، سوئیچ شبکه ۵ پورت ۱۰/۱۰۰، سوئیچ دسکتاپ نتربیت، سوئیچ Fast Ethernet ارزان، سوئیچ بدون فن، گارانتی آونگ',0,'active',0,4,'[\"◉ ۵ پورت ۱۰/۱۰۰ مگابیت بر ثانیه (Fast Ethernet)\",\"◉ ظرفیت سوئیچینگ ۱ گیگابیت بر ثانیه\",\"◉ طراحی بدون فن و کاملاً بی‌صدا\",\"◉ پشتیبانی از IEEE 802.3az – مصرف بهینه انرژی\",\"◉ محافظت در برابر Broadcast Storm – جلوگیری از اختلالات شبکه\",\"◉ گارانتی ۳۶ ماهه آونگ\"]','گارانتی 36 ماهه آونگ','2026-07-19 14:04:32','2026-10-01 11:37:08',NULL),
