(76,'آداپتور 12 ولت 2.5 آمپر دلتا','آداپتور-12-ولت-25-آمپر-دلتا','DLT-12V2.5A-001',24,NULL,'آداپتور ۱۲ ولت ۲.۵ آمپر برند دلتا (Delta) یک منبع تغذیه سوئیچینگ با کیفیت صنعتی است که برای تأمین برق پایدار و مطمئن تجهیزات الکترونیکی حساس طراحی شده است. این آداپتور با توان ۳۰ وات، بازده بالا و حفاظت‌های کامل، گزینه‌ای ایده‌آل برای تأمین برق انواع تجهیزات شبکه، سیستم‌های نظارتی، نئون فلکس، تابلوهای LED و سایر دستگاه‌هایی است که به ولتاژ ۱۲ ولت با جریان ۲.۵ آمپر نیاز دارند.\n\nبرند دلتا الکترونیک (Delta Electronics) یکی از بزرگترین و معتبرترین تولیدکنندگان منابع تغذیه در جهان است. محصولات این برند به دلیل کیفیت ساخت بالا، پایداری فوق‌العاده و طول عمر مفید طولانی، در پروژه‌های صنعتی، تجاری و کاربری‌های حساس به کار گرفته می‌شوند.\n\n','آداپتور سوئیچینگ ۱۲ ولت ۲.۵ آمپر برند دلتا (Delta) یک منبع تغذیه با توان ۳۰ وات و بازده بالا است که برای تأمین برق پایدار تجهیزات حساس مانند تجهیزات شبکه، دوربین‌های مداربسته، دستگاه‌های پزشکی و LED طراحی شده است. این آداپتور با ورودی جهانی ۹۰ تا ۲۶۴ ولت AC، حفاظت‌های کامل و گواهینامه‌های بین‌المللی، انتخابی مطمئن برای کاربران حرفه‌ای محسوب می‌شود.',350000,NULL,50,'/static/uploads/up-1784619394199-cgaa56.jpg','[\"/static/uploads/up-1784619472635-f5kid2.jpg\"]','[{\"group\":\"ورودی\",\"key\":\"ولتاژ ورودی\",\"value\":\"۹۰ تا ۲۶۴ ولت\"},{\"group\":\"ورودی\",\"key\":\"فرکانس ورودی\",\"value\":\"۴۷ تا ۶۳ هرتز (۵۰/۶۰ هرتز)\"},{\"group\":\"ورودی\",\"key\":\"جریان ورودی\",\"value\":\"تا ۱ آمپر\"},{\"group\":\"خروجی\",\"key\":\"ولتاژ خروجی نامی\",\"value\":\"۱۲ ولت DC\"},{\"group\":\"خروجی\",\"key\":\"جریان خروجی نامی\",\"value\":\"۲.۵ آمپر\"},{\"group\":\"خروجی\",\"key\":\"توان خروجی نامی\",\"value\":\"۳۰ وات\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"ابعاد (طول × عرض × ارتفاع)\",\"value\":\"۱۱۰ × ۶۲ × ۳۰ میلی‌متر\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"وزن\",\"value\":\"۲۲۰ تا ۲۵۰ گرم\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"جنس بدنه\",\"value\":\"پلاستیک ABS مقاوم\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"گارانتی اصالت و سلامت فیزیکی کالا\"}]','خرید آداپتور ۱۲ ولت ۲.۵ آمپر دلتا | قیمت منبع تغذیه ۳۰ وات Delta','آداپتور ۱۲ ولت ۲.۵ آمپر برند دلتا با توان ۳۰ وات، بازده بالا، حفاظت‌های کامل و گواهینامه‌های بین‌المللی. مناسب برای تجهیزات شبکه، دوربین مداربسته و LED. گارانتی اصالت و ارسال سریع.\n\n','آداپتور ۱۲ ولت ۲.۵ آمپر دلتا، منبع تغذیه ۱۲ ولت ۲.۵ آمپر Delta، پاور ۳۰ وات دلتا، آداپتور سوئیچینگ دلتا، Delta 12V 2.5A adapter، آداپتور صنعتی دلتا، DRP012V030W1AZ',0,'active',0,0,'[\"◉ خروجی ۱۲ ولت DC با جریان ۲.۵ آمپر – توان ۳۰ وات\",\"◉ ورودی جهانی ۹۰ تا ۲۶۴ ولت AC – قابل استفاده در تمام ایران\",\"◉ راندمان بالا مطابق با استاندارد سطح V – مصرف بهینه انرژی\",\"◉ حفاظت‌های کامل – اتصال کوتاه، اضافه بار، گرمای بیش از حد\",\"◉ مناسب برای تجهیزات شبکه، دوربین مداربسته، LED و مصارف صنعتی\",\"◉ برند دلتا (Delta) – کیفیت صنعتی و قابلیت اطمینان بالا\"]',NULL,'2026-07-21 07:43:06','2026-08-03 23:17:59',NULL),
(77,'کابل شبکه Cat6 UTP تمام مس لگراند مغزی 0.42','کابل-شبکه-cat6-utp-تمام-مس-لگراند-مغزی-042','LEG-CAT6-UTP-042-305',22,1,'کابل شبکه Cat6 UTP لگراند با مغزی تمام مس و قطر ۰.۴۲ میلی‌متر، یکی از پرکاربردترین کابل‌های شبکه در بازار ایران است. این کابل توسط شرکت معتبر فرانسوی لگراند (Legrand) تولید شده و برای ارسال و دریافت اطلاعات و انتقال داده‌ها بدون افت کیفیت طراحی شده است.\n\nتفاوت کابل تمام مس (BC) با CCA: یکی از مهم‌ترین نکات در انتخاب کابل شبکه، جنس مغزی آن است. این کابل با مغزی تمام مس (BC – Bare Copper) تولید می‌شود که در مقایسه با کابل‌های CCA (آلومینیوم با روکش مس) کیفیت انتقال داده بسیار بالاتری دارد.\n\n','کابل شبکه Cat6 UTP لگراند با مغزی تمام مس (BC) و قطر 0.42 میلی‌متر، یک کابل استاندارد و باکیفیت برای شبکه‌های ساختاریافته است. این کابل با پشتیبانی از سرعت انتقال داده تا ۱ گیگابیت بر ثانیه و پهنای باند ۲۵۰ مگاهرتز، برای کابل‌کشی افقی در ساختمان‌های مسکونی، اداری و تجاری ایده‌آل می‌باشد. روکش PVC مقاوم، ساختار ۴ زوج به‌تابیده و بسته‌بندی حلقه ۳۰۵ متری، این محصول را به یکی از پرفروش‌ترین کابل‌های شبکه در بازار ایران تبدیل کرده است.',84108415,NULL,20,'/static/uploads/up-1785394483795-mkmvgc.webp','[\"/static/uploads/up-1784620794210-vhcya5.jpg\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"لگراند\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"UTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۴۲ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد زوج\",\"value\":\"۴ زوج (۸ رشته)\"},{\"group\":\"مشخصات پایه\",\"key\":\"رنگ روکش\",\"value\":\"آبی\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"۱۰/۱۰۰/۱۰۰۰ مگابیت بر ثانیه (۱ گیگابیت بر ثانیه)\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"حداکثر فاصله انتقال\",\"value\":\"۱۰۰ متر\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"تست فلوک\",\"value\":\"بدون تست\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"نوع بسته‌بندی\",\"value\":\"کارتن\"}]','خرید کابل شبکه Cat6 UTP لگراند تمام مس 0.42 | قیمت حلقه 305 متری','کابل شبکه Cat6 UTP لگراند با مغزی تمام مس 0.42 میلی‌متر، پهنای باند ۲۵۰ مگاهرتز و سرعت ۱ گیگابیت بر ثانیه. مناسب برای کابل‌کشی شبکه‌های داخلی. حلقه ۳۰۵ متری با روکش PVC. ارسال سریع و گارانتی اصالت.\n\n','کابل شبکه لگراند، کابل Cat6 UTP، کابل تمام مس لگراند، کابل شبکه 0.42 لگراند، کابل شبکه لگراند ۳۰۵ متری، قیمت کابل لگراند Cat6، Legrand Cat6 UTP cable',0,'active',0,3,'[\"◉ استاندارد CAT6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ مغزی تمام مس (BC) – با قطر ۰.۴۲ میلی‌متر (۲۳ AWG)، رسانایی عالی\",\"◉ ساختار UTP – بدون شیلد، مناسب برای محیط‌های داخلی\",\"◉ ۴ زوج به‌تابیده – کاهش نویز Crosstalk\",\"◉ روکش PVC مقاوم – انعطاف‌پذیر و محافظ در برابر شرایط محیطی\",\"◉ طول ۳۰۵ متر در هر حلقه – بسته‌بندی استاندارد کارتن\"]','','2026-07-21 07:44:03','2026-10-01 13:09:24',NULL),
(78,'کابل شبکه Cat6 UTP تمام مس سوما مغزی 0.48','کابل-شبکه-cat6-utp-تمام-مس-سوما-مغزی-048',NULL,22,NULL,'کابل شبکه Cat6 UTP برند سوما (Souma) با مغزی تمام مس و قطر ۰.۴۸ میلی‌متر، یکی از محصولات تولیدی این برند ایرانی است که برای ارسال و دریافت اطلاعات و انتقال داده‌ها بدون افت کیفیت طراحی شده است. برند سوما به عنوان یکی از تولیدکنندگان داخلی، محصولات خود را با هدف ارائه کیفیت مناسب و قیمت رقابتی به بازار عرضه می‌کند.\n\nکابل شبکه سوما Cat6 UTP با مغزی ۰.۴۸ از ۴ جفت سیم تابیده (۴ Pair Twisted) ساخته شده است. هسته این کابل از مس خالص (CCC) ساخته شده تا اطلاعات را با بالاترین کیفیت انتقال دهد. این کابل معمولاً در متراژ ۳۰۵ متری به بازار عرضه می‌شود.\n\n','کابل شبکه Cat6 UTP برند سوما (Souma) با مغزی تمام مس و قطر 0.48 میلی‌متر، یک کابل استاندارد برای شبکه‌های ساختاریافته است. این کابل با پشتیبانی از سرعت انتقال داده تا ۱ گیگابیت بر ثانیه و پهنای باند ۲۵۰ مگاهرتز، برای کابل‌کشی افقی در ساختمان‌های مسکونی، اداری و تجاری ایده‌آل می‌باشد. روکش PVC مقاوم و ساختار ۴ زوج به‌تابیده، این محصول را به گزینه‌ای مناسب برای پروژه‌های شبکه تبدیل کرده است. برند سوما (Souma) یکی از برندهای ایرانی فعال در حوزه تولید کابل‌های شبکه می‌باشد.',4500,NULL,15,'/static/uploads/up-1784640702512-mrlq5i.jpg','[\"/static/uploads/up-1784640707595-8rqq3l.webp\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"سوما\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"UTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۴۸ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد زوج\",\"value\":\"۴ زوج (۸ رشته)\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس روکش\",\"value\":\"PVC\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"تا ۱ گیگابیت بر ثانیه\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"حداکثر فاصله انتقال\",\"value\":\"۱۰۰ متر\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"تست فلوک\",\"value\":\"بدون تست\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"نوع بسته‌بندی\",\"value\":\"کارتن\"}]','خرید کابل شبکه Cat6 UTP سوما تمام مس 0.48 | قیمت حلقه 305 متری','کابل شبکه Cat6 UTP سوما با مغزی تمام مس 0.48 میلی‌متر، پهنای باند ۲۵۰ مگاهرتز و سرعت ۱ گیگابیت بر ثانیه. مناسب برای کابل‌کشی شبکه‌های داخلی. حلقه ۳۰۵ متری با روکش PVC. ارسال سریع و گارانتی اصالت.\n\n','کابل شبکه سوما، کابل Cat6 UTP، کابل تمام مس سوما، کابل شبکه 0.48 سوما، قیمت کابل سوما Cat6، Souma Cat6 UTP cable',0,'active',0,1,'[\"◉ استاندارد Cat6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ مغزی تمام مس (CCC) – با قطر ۰.۴۸ میلی‌متر، رسانایی عالی\",\"◉ ساختار UTP (بدون شیلد) – مناسب برای محیط‌های داخلی\",\"◉ روکش PVC مقاوم – انعطاف‌پذیر و محافظ در برابر شرایط محیطی\",\"◉ طول ۳۰۵ متر در هر حلقه – بسته‌بندی استاندارد کارتن\",\"◉ برند سوما (Souma) – تولیدکننده ایرانی، جایگزین اقتصادی لگراند\"]',NULL,'2026-07-21 13:38:35','2026-08-03 23:17:59',NULL),
(79,'کابل شبکه Cat6 UTP تمام مس سوما مغزی 0.50','کابل-شبکه-cat6-utp-تمام-مس-سوما-مغزی-050','SOM-CAT6-UTP-050-305',22,NULL,'کابل شبکه Cat6 UTP برند سوما (Souma) با مغزی تمام مس و قطر ۰.۵۰ میلی‌متر، یکی از محصولات تولیدی این برند ایرانی است که برای ارسال و دریافت اطلاعات و انتقال داده‌ها بدون افت کیفیت طراحی شده است. برند سوما (Souma) با نام شرکت صنعت شتاب کابل، به عنوان یکی از تولیدکنندگان داخلی، محصولات خود را با هدف ارائه کیفیت مناسب و قیمت رقابتی به بازار عرضه می‌کند.\n\nکابل شبکه سوما Cat6 UTP با مغزی ۰.۵۰ از ۴ جفت سیم تابیده (۴ Pair Twisted) ساخته شده است. هسته این کابل از مس خالص (CCC) ساخته شده تا اطلاعات را با بالاترین کیفیت انتقال دهد. این کابل معمولاً در متراژ ۳۰۵ متری به بازار عرضه می‌شود.\n\n','کابل شبکه Cat6 UTP برند سوما (Souma) با مغزی تمام مس و قطر 0.50 میلی‌متر، یک کابل استاندارد برای شبکه‌های ساختاریافته است. این کابل با پشتیبانی از سرعت انتقال داده تا ۱ گیگابیت بر ثانیه و پهنای باند ۲۵۰ مگاهرتز، برای کابل‌کشی افقی در ساختمان‌های مسکونی، اداری و تجاری ایده‌آل می‌باشد. روکش PVC مقاوم و ساختار ۴ زوج به‌تابیده، این محصول را به گزینه‌ای مناسب برای پروژه‌های شبکه تبدیل کرده است. برند سوما (Souma) یکی از برندهای ایرانی فعال در حوزه تولید کابل‌های شبکه می‌باشد.',47824,NULL,15,'/static/uploads/up-1785394497195-etlmqx.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"سوما\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"UTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۵۰ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد زوج\",\"value\":\"۴ زوج (۸ رشته)\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"تا ۱ گیگابیت بر ثانیه\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"حداکثر فاصله انتقال\",\"value\":\"۱۰۰ متر\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر (معمولاً)\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"نوع بسته‌بندی\",\"value\":\"کارتن\"}]','خرید کابل شبکه Cat6 UTP سوما 0.50 | قیمت جایگزین لگراند','کابل شبکه Cat6 UTP سوما با مغزی تمام مس 0.50 میلی‌متر، پهنای باند ۲۵۰ مگاهرتز و سرعت ۱ گیگابیت. مناسب برای کابل‌کشی شبکه‌های داخلی. حلقه ۳۰۵ متری با روکش PVC. ارسال سریع و گارانتی اصالت.\n\n','کابل شبکه سوما، کابل Cat6 UTP، کابل تمام مس 0.50، کابل شبکه ۳۰۵ متری، قیمت کابل Cat6، Souma Cat6 cable',0,'active',0,1,'[\"◉ استاندارد Cat6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ ساختار UTP (بدون شیلد) – مناسب برای محیط‌های داخلی\",\"◉ ۴ زوج به‌تابیده – کاهش نویز Crosstalk\",\"◉ روکش PVC مقاوم – انعطاف‌پذیر و محافظ در برابر شرایط محیطی\",\"◉ طول ۳۰۵ متر در هر حلقه – بسته‌بندی استاندارد کارتن\",\"◉ برند سوما (Souma) – تولیدکننده ایرانی، جایگزین اقتصادی لگراند\"]','','2026-07-21 14:15:38','2026-08-03 23:17:59',NULL),
(80,'کابل شبکه اوت دور نگزنس sftp cat6 دو روکش مس 040','کابل-شبکه-اوت-دور-نگزنس-sftp-cat6-دو-روکش-مس-040','NEX-SFTP-CAT6-040-305',23,11,'کابل شبکه اوت‌دور نگزنس (Nexans) از نوع SFTP Cat6 با دو روکش و مغزی تمام مس ۰.۴۰ میلی‌متر، یک کابل حرفه‌ای و فوق‌مقاوم برای کابل‌کشی در فضای باز است. برند نگزنس یکی از معتبرترین تولیدکنندگان کابل‌های شبکه در جهان است و محصولات آن با استانداردهای بین‌المللی و گارانتی ۲۰ ساله عرضه می‌شوند.\n\nاین کابل با ساختار شیلددار کامل (SFTP)، دو روکش و مغزی تمام مس، برای محیط‌هایی با شرایط جوی سخت، نویز الکترومغناطیسی بالا و نیاز به انتقال پایدار داده طراحی شده است.\n\n','کابل شبکه اوت‌دور نگزنس (Nexans) از نوع SFTP Cat6 با دو روکش و مغزی تمام مس ۰.۴۰ میلی‌متر، یک کابل حرفه‌ای و مقاوم برای کابل‌کشی در فضای باز است. این کابل با ساختار شیلددار (SFTP) در برابر تداخل الکترومغناطیسی، رطوبت، اشعه UV و شرایط جوی سخت مقاوم بوده و برای شبکه‌های بین‌ساختمانی، دوربین‌های مداربسته فضای باز، دیتاسنترها و پروژه‌های زیرساختی ایده‌آل می‌باشد.',154,NULL,10,'/static/uploads/up-1784700493124-6wswdi.jpg','[\"/static/uploads/up-1784700496398-jk9wig.jpg\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"نگزنس\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"SFTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۴۰ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد روکش\",\"value\":\"۲ روکش\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"تا ۱ گیگابیت بر ثانیه\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"حداکثر فاصله انتقال\",\"value\":\"۱۰۰ متر\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"مقاومت در برابر UV\",\"value\":\"دارد\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر\"}]','خرید کابل اوت‌دور نگزنس SFTP Cat6 0.40 | قیمت کابل دو روکش Nexans','کابل شبکه اوت‌دور Nexans SFTP Cat6 با دو روکش ضدآب و ضد UV، مغزی تمام مس 0.40 میلی‌متر. مناسب برای کابل‌کشی فضای باز، دوربین مداربسته و شبکه‌های حساس. گارانتی اصالت و ارسال سریع.\n\n','کابل شبکه اوت‌دور نگزنس، کابل SFTP Cat6، کابل دو روکش Nexans، کابل ضدآب شبکه، کابل فضای باز Cat6، قیمت کابل نگزنس، Nexans outdoor cable',0,'active',0,2,'[\"◉ استاندارد Cat6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ مغزی تمام مس (BC) – با قطر ۰.۴۰ میلی‌متر، رسانایی عالی\",\"◉ ساختار SFTP (شیلددار کامل) – شیلد + فویل، مقاوم در برابر نویز و تداخل الکترومغناطیسی\",\"◉ دو روکش (Double Sheath) – مقاوم در برابر رطوبت، اشعه UV و شرایط جوی سخت\",\"◉ مناسب برای نصب اوت‌دور (Outdoor) – ضدآب، ضد UV، قابل استفاده در فضای باز\"]','','2026-07-22 05:58:52','2026-08-03 23:17:59',NULL),
(81,'کابل شبکه اوت دور نگزنس sftp cat6 دو روکش مس 045','کابل-شبکه-اوت-دور-نگزنس-sftp-cat6-دو-روکش-مس-045','NEX-SFTP-CAT6-045-305',23,11,'کابل شبکه اوت‌دور نگزنس (Nexans) از نوع SFTP Cat6 با دو روکش و مغزی تمام مس ۰.۴۵ میلی‌متر، یک کابل حرفه‌ای و فوق‌مقاوم برای کابل‌کشی در فضای باز است. برند نگزنس یکی از معتبرترین تولیدکنندگان کابل‌های شبکه در جهان است و محصولات آن با استانداردهای بین‌المللی و گارانتی ۲۰ ساله عرضه می‌شوند.\n\n','کابل شبکه اوت‌دور Nexans SFTP Cat6 با دو روکش و مغزی تمام مس ۰.۴۵ میلی‌متر، یک کابل حرفه‌ای برای کابل‌کشی در فضای باز است. این کابل با ساختار شیلددار (SFTP) در برابر تداخل الکترومغناطیسی، رطوبت، اشعه UV و شرایط جوی سخت مقاوم بوده و برای شبکه‌های بین‌ساختمانی، دوربین‌های مداربسته فضای باز و پروژه‌های زیرساختی ایده‌آل می‌باشد.',848,NULL,15,'/static/uploads/up-1784700463196-u8aazz.jpg','[\"/static/uploads/up-1784700479420-cyyop2.jpg\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"نگزنس\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"SFTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۴۵ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد روکش\",\"value\":\"۲ روکش\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"سرعت انتقال داده\",\"value\":\"تا ۱ گیگابیت بر ثانیه\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"حداکثر فاصله انتقال\",\"value\":\"۱۰۰ متر\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"مقاومت در برابر UV\",\"value\":\"دارد\"},{\"group\":\"عملکرد و استانداردها\",\"key\":\"مقاومت در برابر آب و رطوبت\",\"value\":\"دارد\"}]','خرید کابل اوت‌دور نگزنس SFTP Cat6 0.45 | قیمت کابل دو روکش Nexans','کابل شبکه اوت‌دور Nexans SFTP Cat6 با دو روکش ضدآب و ضد UV، مغزی تمام مس 0.45 میلی‌متر. مناسب برای کابل‌کشی فضای باز، دوربین مداربسته و شبکه‌های حساس. گارانتی اصالت و ارسال سریع.\n\n','کابل شبکه اوت‌دور نگزنس، کابل SFTP Cat6، کابل دو روکش Nexans، کابل ضدآب شبکه، کابل فضای باز Cat6، قیمت کابل نگزنس',0,'active',0,0,'[\"◉ استاندارد Cat6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ نوع SFTP (شیلددار کامل) – شیلد بافت + فویل برای هر زوج، مقاوم در برابر نویز و EMI\",\"◉ مغزی تمام مس (BC) – با قطر ۰.۴۵ میلی‌متر، رسانایی عالی و کاهش افت سیگنال\",\"◉ دو روکش (Double Sheath) – روکش داخلی PE + روکش خارجی ضد UV و ضدآب\",\"◉ مناسب برای نصب اوت‌دور (Outdoor) – مقاوم در برابر رطوبت، باران، برف و تابش مستقیم خورشید\"]','','2026-07-22 06:06:08','2026-08-03 23:17:59',NULL),
(82,'کابل شبکه sftp تمام مس تست چنل','کابل-شبکه-sftp-تمام-مس-تست-چنل','CAB-SFTP-CH-06-305',23,1,'تست چنل (Channel Test) یکی از دقیق‌ترین و معتبرترین تست‌های کابل‌کشی ساختاریافته است که توسط دستگاه Fluke Networks (و یا برندهای معادل) انجام می‌شود. این تست، عملکرد کامل یک مسیر ارتباطی (Channel) را از پچ پنل تا پریز دیواری (شامل کابل، پچ کورد، کانکتورها و پچ پنل) در شرایط واقعی شبیه‌سازی می‌کند.\n\n','کابل شبکه SFTP تمام مس با تست چنل (Fluke Channel Test)، یک کابل حرفه‌ای و درجه یک برای شبکه‌های حساس و پروژه‌های بزرگ سازمانی است. این کابل با ساختار شیلددار کامل (SFTP) و مغزی تمام مس، بالاترین سطح کیفیت انتقال داده را در محیط‌های با نویز الکترومغناطیسی بالا ارائه می‌دهد. تست چنل معتبر، عملکرد کامل کابل را در مسیر ۱۰۰ متری با تمام تجهیزات جانبی تضمین می‌کند و همراه با گارانتی ۲۰ ساله از برندهای معتبر عرضه می‌شود.',45,NULL,15,'/static/uploads/up-1784704084126-qkz9kh.jpg','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"SFTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"}]','خرید کابل شبکه SFTP تمام مس تست چنل | قیمت کابل شیلددار Cat6','کابل شبکه SFTP تمام مس با تست چنل (Fluke Channel Test)، مناسب برای شبکه‌های حساس و پروژه‌های بزرگ. دارای شیلد کامل، مقاوم در برابر نویز و گارانتی ۲۰ ساله. ارسال سریع و گارانتی اصالت.\n\n','کابل SFTP، کابل تمام مس، تست چنل، Fluke Channel Test، کابل شبکه شیلددار، کابل Cat6 SFTP، کابل شبکه تست فلوک',0,'active',0,0,'[\"◉ استاندارد Cat6/Cat6a – پهنای باند ۲۵۰ تا ۵۰۰ مگاهرتز، سرعت تا ۱۰ گیگابیت بر ثانیه\",\"◉ نوع SFTP (شیلددار کامل) – شیلد بافت + فویل برای هر زوج، مقاوم در برابر نویز و EMI\",\"◉ مغزی تمام مس (BC) – رسانایی عالی و کاهش افت سیگنال\",\"◉ تست چنل (Fluke Channel Test) – تضمین عملکرد کامل در مسیر ۱۰۰ متری با تجهیزات جانبی\",\"◉ مناسب برای دیتاسنتر و شبکه‌های حساس سازمانی – بانک‌ها، بیمارستان‌ها، محیط‌های صنعتی\",\"◉ گارانتی ۲۰ ساله – همراه با مدارک تست معتبر (در برندهای اصلی)\"]',NULL,'2026-07-22 07:08:08','2026-08-03 23:17:59',NULL),
(83,'کابل شبکه Cat6 لگراند UTP تست پرمننت مغزی 57','کابل-شبکه-cat6-لگراند-utp-تست-پرمننت-مغزی-57','LEG-CAT6-UTP-057-305',22,1,'کابل شبکه Cat6 UTP لگراند (Legrand) با تست پرمننت (Permanent Link) و مغزی تمام مس ۰.۵۷ میلی‌متر، یک کابل حرفه‌ای و درجه یک برای شبکه‌های ساختاریافته است. برند لگراند یکی از معتبرترین تولیدکنندگان تجهیزات شبکه در جهان است و محصولات آن با بالاترین استانداردهای کیفی و گارانتی ۲۵ ساله عرضه می‌شوند.\n\nاین کابل با قطر مغزی ۰.۵۷ میلی‌متر (معادل 23 AWG)، رسانایی عالی و افت سیگنال بسیار کمی در مسافت‌های طولانی دارد و برای پروژه‌های سازمانی، دیتاسنترها و کابل‌کشی‌های حساس ایده‌آل است. تست پرمننت معتبر نیز عملکرد کابل را در مسیر دائمی (بدون پچ کورد) تضمین می‌کند.\n\n\n','کابل شبکه Cat6 UTP لگراند با تست پرمننت (Permanent Link) و مغزی تمام مس ۰.۵۷ میلی‌متر، یک کابل حرفه‌ای و استاندارد برای شبکه‌های ساختاریافته است. این کابل با پشتیبانی از سرعت انتقال داده تا ۱ گیگابیت بر ثانیه و پهنای باند ۲۵۰ مگاهرتز، همراه با گارانتی ۲۵ ساله لگراند، انتخابی ایده‌آل برای پروژه‌های سازمانی، دیتاسنترها و کابل‌کشی‌های حساس می‌باشد.',5005,NULL,13,'/static/uploads/up-1785394509895-uuf4je.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"لگراند\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"UTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۵۷\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"قطر خارجی کابل\",\"value\":\"~۶.۰ میلی‌متر\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر\"},{\"group\":\"فیزیکی و محیطی\",\"key\":\"نوع بسته‌بندی\",\"value\":\"کارتن\"}]','خرید کابل Cat6 لگراند تست پرمننت 0.57 | قیمت کابل Legrand ','کابل شبکه Cat6 UTP لگراند با تست پرمننت و مغزی تمام مس 0.57 میلی‌متر، مناسب برای شبکه‌های سازمانی و دیتاسنتر. دارای گارانتی ۲۵ ساله و تست فلوک معتبر. ارسال سریع و گارانتی اصالت.\n\n','کابل شبکه لگراند، کابل Cat6 UTP، تست پرمننت، Permanent Link Test، کابل لگراند 0.57، کابل شبکه ۳۰۵ متری، Legrand Cat6 cable',0,'active',1,22,'[\"◉ استاندارد Cat6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ مغزی تمام مس (BC) با قطر ۰.۵۷ میلی‌متر – رسانایی عالی و کاهش افت سیگنال\",\"◉ تست پرمننت (Permanent Link) – تضمین عملکرد در مسیر دائمی با دستگاه Fluke\",\"◉ ساختار UTP (بدون شیلد) – مناسب برای محیط‌های داخلی و اداری\"]','','2026-07-22 10:30:53','2026-10-01 16:42:04',NULL),
(84,'مودم روتر ۴G LTE نتربیت مدل NW-421F','مودم-روتر-۴g-lte-نتربیت-مدل-nw-421f','NET-NW421F-001',26,3,'مودم روتر ۴G LTE نتربیت مدل NW-421F یک راه‌حل کامل و مقرون‌به‌صرفه برای برقراری اینترنت پرسرعت در مناطقی است که دسترسی به ADSL، VDSL یا فیبر نوری محدود است یا به عنوان یک اتصال پشتیبان در کنار خطوط ثابت عمل می‌کند. این دستگاه با استفاده از یک سیم‌کارت ۴G (همراه اول، ایرانسل، رایتل یا شاتل موبایل) اینترنت موبایل را به یک شبکه وای‌فای قدرتمند با پوشش گسترده و پورت‌های سیمی تبدیل می‌کند.\n\nبرند نتربیت (Neterbit) با پشتوانه دانش متخصصان و محققان تایوانی و بر اساس لایسنس فعالیت می‌کند و محصولات خود را از سال ۱۳۹۸ به بازار عرضه کرده است. این برند با ارائه گارانتی ۱۸ ماهه آونگ، اطمینان خاطر بیشتری را برای خریداران فراهم می‌کند.\n\n','مودم روتر ۴G LTE نتربیت مدل NW-421F یک دستگاه جمع‌وجور و کارآمد برای تبدیل اینترنت سیم‌کارت به وای‌فای و پورت‌های سیمی است. این مودم با سرعت دانلود تا ۱۵۰ مگابیت بر ثانیه، وای‌فای N300 با ۴ آنتن خارجی (۲ آنتن LTE + ۲ آنتن وای‌فای)، ۳ پورت LAN و پشتیبانی از تمام اپراتورهای ایرانی، انتخابی مناسب برای منازل، دفاتر کوچک و مناطقی با دسترسی محدود به اینترنت ثابت می‌باشد.',4950001,NULL,10,'/static/uploads/up-1784716429634-0qq5hv.jpg','[\"/static/uploads/up-1784716517327-424cve.jpg\"]','[{\"group\":\"شبکه موبایل\",\"key\":\"نسل شبکه\",\"value\":\"۴G LTE Cat4 / ۳G / ۲G\"},{\"group\":\"شبکه موبایل\",\"key\":\"سرعت دانلود (LTE)\",\"value\":\"تا ۱۵۰ مگابیت بر ثانیه\"},{\"group\":\"شبکه موبایل\",\"key\":\"سرعت آپلود (LTE)\",\"value\":\"تا ۵۰ مگابیت بر ثانیه\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"پورت LAN\",\"value\":\"۳ عدد RJ45 ۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"گارانتی\",\"key\":\"گارانتی\",\"value\":\"36 ماه گارانتی آونگ\"}]','خرید مودم ۴G LTE نتربیت NW-421F | قیمت روتر سیمکارتی N300','مودم روتر 4G LTE نتربیت مدل NW-421F با سرعت دانلود ۱۵۰ مگابیت، وای‌فای N300، ۴ آنتن خارجی و گارانتی ۱۸ ماهه آونگ. مناسب برای منزل، اداره و اینترنت پشتیبان. ارسال سریع.\n\n','مودم ۴G، نتربیت NW-421F، روتر LTE، مودم سیمکارتی، مودم همراه اول، مودم ایرانسل، مودم ۴G نتربیت، خرید مودم ۴G، Neterbit NW-421F',0,'active',0,1,'[\"◉ ۴G LTE Cat4 – سرعت دانلود ۱۵۰ مگابیت، آپلود ۵۰ مگابیت\",\"◉ وای‌فای N300 – باند ۲.۴ گیگاهرتز، سرعت تا ۳۰۰ مگابیت بر ثانیه\",\"◉ ۳ پورت LAN – اتصال سیمی ۱۰/۱۰۰ مگابیت\",\"◉ منبع تغذیه USB Type-C – ۵ ولت / ۲ آمپر\",\"◉ امنیت – رمزگذاری WPA/WPA2\",\"◉ گارانتی 36 ماهه آونگ\"]','گارانتی 36 ماهه آونگ','2026-07-22 10:53:24','2026-09-19 13:13:20',NULL),
(85,'سوییچ شبکه 8 پورت تی پی لینک مدل LS-1008','سوییچ-شبکه-8-پورت-تی-پی-لینک-مدل-ls-1008','TPL-LS1008-001',21,4,'سوییچ شبکه ۸ پورت Fast Ethernet تی‌پی‌لینک مدل LS1008 یکی از محصولات سری LiteWave این شرکت است که راه‌حلی ساده، مقرون‌به‌صرفه و کارآمد برای افزایش پورت‌های شبکه در منازل، دفاتر کوچک و محیط‌های آموزشی ارائه می‌دهد. این سوییچ با ۸ پورت ۱۰/۱۰۰ مگابیت بر ثانیه، امکان اتصال همزمان چندین دستگاه مانند کامپیوتر، لپ‌تاپ، پرینتر، دوربین مداربسته، تلویزیون هوشمند و کنسول بازی را فراهم می‌کند.','سوییچ شبکه ۸ پورت تی‌پی‌لینک مدل LS1008 یک دستگاه غیرمدیریتی و جمع‌وجور از سری LiteWave است که برای افزایش پورت‌های شبکه در منازل، دفاتر کوچک و محیط‌های آموزشی طراحی شده است. این سوییچ با ۸ پورت ۱۰/۱۰۰ مگابیت بر ثانیه، ظرفیت سوئیچینگ ۱.۶ گیگابیت بر ثانیه و طراحی بدون فن، نصب آسان و عملکردی بی‌صدا و کم‌مصرف را ارائه می‌دهد.',524,NULL,0,'/static/uploads/up-1784717910503-dsr7ye.webp','[]','[{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"تعداد پورت\",\"value\":\"۸ عدد\"},{\"group\":\"پورت‌ها و اتصالات\",\"key\":\"سرعت پورت\",\"value\":\"۱۰/۱۰۰ مگابیت بر ثانیه\"},{\"group\":\"فیزیکی و برق\",\"key\":\"وزن\",\"value\":\"۱۲۰ گرم\"}]','خرید سوییچ 8 پورت تی پی لینک LS1008 | قیمت TP-Link','سوییچ ۸ پورت تی‌پی‌لینک مدل LS1008 با سرعت ۱۰/۱۰۰ مگابیت، ظرفیت سوئیچینگ ۱.۶ گیگابیت و طراحی بدون فن. مناسب برای منزل و اداره. نصب Plug and Play و گارانتی ۳۶ ماهه. ارسال سریع.\n\n','سوییچ تی پی لینک LS1008، سوییچ ۸ پورت تی پی لینک، TP-Link LS1008، سوییچ شبکه ۸ پورت ۱۰/۱۰۰، سوییچ دسکتاپ تی پی لینک، سوییچ Fast Ethernet، سوییچ بدون فن، TP-Link LiteWave',0,'active',0,1,'[\"◉ ۸ پورت ۱۰/۱۰۰ مگابیت بر ثانیه (Fast Ethernet)\",\"◉ ظرفیت سوئیچینگ ۱.۶ گیگابیت بر ثانیه\",\"◉ فناوری Green Ethernet – کاهش مصرف برق تا ۶۰٪\",\"◉ Auto MDI/MDIX خودکار – بدون نیاز به کابل کراس\",\"◉ ابعاد فوق‌فشرده (۱۲۴.۶×۴۸.۷×۲۲.۸ میلی‌متر)\",\"◉ گارانتی ۳۶ ماهه\"]',NULL,'2026-07-22 11:01:43','2026-09-19 13:13:21',NULL),
(86,'کابل شبکه sftp تمام مس بدون تست','کابل-شبکه-sftp-تمام-مس-بدون-تست','CAB-SFTP-CAT6-UNTESTED-305',23,1,'کابل شبکه Cat6 SFTP با مغزی تمام مس و بدون تست فلوک، یک انتخاب اقتصادی و هوشمندانه برای پروژه‌هایی است که به کیفیت بالا نیاز دارند اما نیازی به ارائه مدارک تست رسمی (مانند تست چنل یا پرمننت) ندارند. این کابل با ساختار شیلددار (SFTP) خود، در برابر نویزهای الکترومغناطیسی و تداخلات محیطی مقاومت بالایی دارد و برای محیط‌های اداری، خانگی و حتی صنعتی سبک مناسب است.\n\nبرندهای معتبری مانند لگراند (Legrand) و نگزنس (Nexans) این محصول را با کیفیت ساخت بالا و متریال درجه یک عرضه می‌کنند.','کابل شبکه Cat6 SFTP با مغزی تمام مس و بدون تست فلوک، گزینه‌ای اقتصادی برای پروژه‌هایی است که به مستندات تست رسمی نیاز ندارند. ساختار شیلددار (SFTP) آن با ترکیب شیلد بافته‌شده و فویل آلومینیومی، محافظت مناسبی در برابر نویز و تداخل الکترومغناطیسی ایجاد می‌کند. این کابل برای محیط‌های اداری، خانگی و صنعتی سبک ایده‌آل است و برندهای معتبری مانند لگراند (Legrand) و نگزنس (Nexans) آن را با روکش PVC یا LSZH و در متراژهای ۳۰۵ و ۵۰۰ متری عرضه می‌کنند.',1510,NULL,15,'/static/uploads/up-1785393128695-ep5r7f.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"برند\",\"value\":\"لگراند\"},{\"group\":\"مشخصات پایه\",\"key\":\"دسته‌بندی\",\"value\":\"Cat6\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کابل\",\"value\":\"SFTP\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس مغزی\",\"value\":\"تمام مس\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر مغزی\",\"value\":\"۰.۴۰\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد زوج\",\"value\":\"۴ زوج\"},{\"group\":\"عملکرد\",\"key\":\"سرعت انتقال داده\",\"value\":\"تا ۱ گیگابیت بر ثانیه\"},{\"group\":\"عملکرد\",\"key\":\"تست فلوک\",\"value\":\"ندارد\"},{\"group\":\"فیزیکی\",\"key\":\"متراژ هر حلقه\",\"value\":\"۳۰۵ متر\"}]','خرید کابل Cat6 SFTP تمام مس بدون تست | قیمت لگراند و نگزنس','کابل شبکه Cat6 SFTP تمام مس بدون تست فلوک از برندهای لگراند و نگزنس. مناسب برای پروژه‌های اقتصادی با مقاومت بالا در برابر نویز. قیمت مناسب و ارسال سریع.\n\n','کابل SFTP، کابل تمام مس، بدون تست فلوک، کابل شبکه لگراند، کابل شبکه نگزنس، کابل Cat6، کابل شیلددار',0,'active',0,2,'[\"◉ استاندارد Cat6 – پهنای باند ۲۵۰ مگاهرتز، سرعت ۱ گیگابیت بر ثانیه\",\"◉ مغزی تمام مس (Bare Copper) – رسانایی عالی و کاهش افت سیگنال\",\"◉ بدون تست فلوک – گزینه‌ای اقتصادی برای پروژه‌های بدون نیاز به مستندات تست\",\"◉ ۴ زوج به‌تابیده با شیلد مجزا – کاهش نویز Crosstalk\",\"◉ روکش PVC یا LSZH – بسته به مدل، مناسب برای محیط‌های داخلی\",\"◉ متراژ ۳۰۵ یا ۵۰۰ متر – بسته‌بندی کارتن یا قرقره\"]','','2026-07-22 13:18:07','2026-10-01 13:02:33',NULL),
(87,'کم باکس پرو مدل 14*14','کم-باکس-پرو-مدل-1414','cambox-pro-14x14-ca-14w',33,NULL,'کم باکس پرو مدل ۱۴×۱۴ (CAMBOX PRO – CA-14W) یک جعبه اتصال (Combo Box) استاندارد و پرکاربرد در صنعت نظارت تصویری است که برای محافظت و سازماندهی اصولی اتصالات، آداپتورها و تجهیزات جانبی دوربین‌های مداربسته طراحی شده است. این محصول با ابعاد ۱۴×۱۴×۵.۵ سانتی‌متر، فضایی ایده‌آل برای قرارگیری همزمان آداپتور برق دوربین، اتصالات BNC و DC، سوئیچ‌های کوچک و سایر تجهیزات جانبی فراهم می‌کند و انتخابی مناسب برای پروژه‌های نصب و راه‌اندازی سیستم‌های نظارتی در محیط‌های مختلف است.','کمباکس پرو مدل ۱۴×۱۴ (CA-14W) یک جعبه اتصال استاندارد و مقاوم برای نصب حرفه‌ای دوربین‌های مداربسته است. این محصول با ابعاد ۱۴×۱۴×۵.۵ سانتی‌متر، بدنه پلاستیکی مهندسی‌شده با خاصیت Anti-UV، درب لولایی بازشونده با لولاهای مقاوم و درجه حفاظت IP65، گزینه‌ای ایده‌آل برای عایق‌سازی دوربین از محل نصب، حذف نویز تصویر، محافظت در برابر رعد و برق و نظم‌دهی به کابل‌ها و اتصالات در محیط‌های داخلی و خارجی می‌باشد.',200000,NULL,50,'/static/uploads/up-1785394682795-9jquy7.webp','[]','[{\"group\":\"ابعاد و فیزیکی\",\"key\":\"مدل\",\"value\":\"CA-14W / CamBox Pro 14\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"ابعاد خارجی (طول × عرض × ارتفاع)\",\"value\":\"۱۴۰ × ۱۴۰ × ۵۵\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"رنگ\",\"value\":\"۲۹۵ گرم\"},{\"group\":\"مقاومت و محافظت\",\"key\":\"استاندارد مقاومتی\",\"value\":\"IP65 – مقاوم در برابر گرد و غبار و پاشش آب\"},{\"group\":\"مقاومت و محافظت\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"دارد\"},{\"group\":\"بسته‌بندی\",\"key\":\"تعداد در هر کارتن\",\"value\":\"۵۴ عدد\"}]','خرید کم باکس پرو ۱۴×۱۴ CA-14W | قیمت جعبه اتصال دوربین CAMBOX','کم باکس پرو ۱۴×۱۴ با درب لولایی، بدنه ABS مقاوم در برابر ضربه و UV، درجه حفاظت IP65 و گارانتی مادام‌العمر. مناسب برای اتصالات و آداپتور دوربین مداربسته در فضای باز و داخلی.\n\n','کمباکس پرو ۱۴×۱۴، کمباکس CA-14W، جعبه اتصال دوربین مداربسته، Cambox Pro 14، کم باکس لولایی پرو، کم باکس سفید ۱۴ در ۱۴، ارکو پلاست، جعبه تقسیم روکار',0,'active',0,4,'[\"◉ ابعاد ۱۴×۱۴×۵.۵ سانتی‌متر – فضای کافی برای آداپتور و اتصالات\",\"◉ استاندارد IP65 – مقاوم در برابر گرد و غبار و پاشش آب\",\"◉ درب لولایی بازشونده با لولاهای مقاوم – دسترسی آسان به داخل باکس\",\"◉ عایق‌سازی دوربین از محل نصب – حذف نویز تصویر و محافظت در برابر رعد و برق\",\"◉ قابلیت نصب گلند و مدیریت منظم کابل‌ها\",\"◉ گارانتی مادام‌العمر (برند CAMBOX)\"]','','2026-07-22 13:29:24','2026-10-01 16:39:37',NULL),
(88,'کم باکس پرو مدل 12*12','کم-باکس-پرو-مدل-1212','CAM-PRO-12X12',33,NULL,'کمباکس پرو مدل ۱۲×۱۲ (CAMBOX PRO – CA-12W) یک جعبه اتصال (Combo Box) استاندارد و پرکاربرد در صنعت نظارت تصویری است که برای محافظت و سازماندهی اصولی اتصالات، آداپتورها و تجهیزات جانبی دوربین‌های مداربسته طراحی شده است. این محصول با ابعاد ۱۲×۱۲×۴.۵ سانتی‌متر، فضایی ایده‌آل برای قرارگیری همزمان آداپتور برق دوربین، اتصالات BNC و DC و سایر تجهیزات جانبی فراهم می‌کند و انتخابی مناسب برای پروژه‌های نصب و راه‌اندازی سیستم‌های نظارتی در محیط‌های مختلف است.\n\nبرند اصلی و معتبر این محصول، CAMBOX (ارکو پلاست / شرکت ارتباط روشن) است که محصولات خود را با کیفیت بالا و گارانتی مادام‌العمر عرضه می‌کند.\n\n','کمباکس پرو مدل ۱۲×۱۲ (CA-12W) یک جعبه اتصال استاندارد و مقاوم برای نصب حرفه‌ای دوربین‌های مداربسته در محیط‌های داخلی و خارجی است. این محصول با ابعاد ۱۲×۱۲×۴.۵ سانتی‌متر، بدنه پلی‌پروپیلن مهندسی‌شده با خاصیت Anti-UV، درب لولایی بازشونده با لولاهای مقاوم و گارانتی مادام‌العمر، گزینه‌ای ایده‌آل برای عایق‌سازی دوربین از محل نصب، حذف نویز تصویر، محافظت در برابر رعد و برق و نظم‌دهی به کابل‌ها و اتصالات می‌باشد.',50,NULL,50,'/static/uploads/up-1785394693296-exedz4.webp','[]','[{\"group\":\"ابعاد و فیزیکی\",\"key\":\"مدل\",\"value\":\"CA-12W / CamBox Pro 12\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"رنگ\",\"value\":\"سفید\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"وزن\",\"value\":\"۱۹۵ گرم\"},{\"group\":\"مقاومت و محافظت\",\"key\":\"استاندارد مقاومتی\",\"value\":\"IP64 – مقاوم در برابر گرد و غبار و پاشش آب\"},{\"group\":\"مقاومت و محافظت\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"دارد (Anti-UV)\"},{\"group\":\"مقاومت و محافظت\",\"key\":\"مقاوم در برابر ضربه\",\"value\":\"دارد (بدنه تقویت‌شده)\"},{\"group\":\"بسته‌بندی\",\"key\":\"گارانتی\",\"value\":\"گارانتی مادام‌العمر\"},{\"group\":\"بسته‌بندی\",\"key\":\"تعداد در هر کارتن\",\"value\":\"۸۵ عدد\"}]','خرید کمباکس پرو ۱۲×۱۲ CA-12W | قیمت جعبه اتصال دوربین CAMBOX','کمباکس پرو ۱۲×۱۲ با درب لولایی، بدنه ABS مقاوم در برابر ضربه و UV، درجه حفاظت IP64 و گارانتی