(101,'پلی فلکس سفید سایز 21','پلی-فلکس-سفید-سایز-21','PLX-WH-21-25',18,NULL,'لوله پلی فلکس سفید سایز ۲۱ که با نام‌های لوله خرطومی پلی‌اتیلن یا پلی فلکس ۲۱ نیز شناخته می‌شود، یکی از پرکاربردترین تجهیزات محافظتی در صنعت برق، شبکه و مخابرات است. این لوله از جنس پلی‌اتیلن باکیفیت ساخته شده و جایگزینی سبک، منعطف و مقرون‌به‌صرفه برای لوله‌های فلکسی فلزی محسوب می‌شود.\n\nلوله‌های پلی فلکس به دلیل انعطاف‌پذیری بالا، امکان عبور کابل‌ها از مسیرهای پیچیده، زوایا و فضاهای محدود را فراهم می‌کنند. سایز ۲۱ این لوله‌ها با قطر داخلی ۲۱ میلی‌متر و قطر خارجی ۲۵ میلی‌متر，برای محافظت از کابل‌های با ضخامت بیشتر یا تعداد بیشتری کابل به‌صورت همزمان، انتخاب مناسبی است.\n\n','لوله پلی فلکس سفید سایز ۲۱ یک لوله خرطومی پلی‌اتیلن با قطر داخلی ۲۱ میلی‌متر است که برای محافظت و هدایت کابل‌های برق، شبکه و دوربین مداربسته در محیط‌های داخلی و خارجی طراحی شده است. این لوله با وزن سبک، انعطاف‌پذیری بالا، مقاومت در برابر اشعه UV و رطوبت، گزینه‌ای ایده‌آل برای پروژه‌های بزرگ‌تر ساختمانی و تأسیسات برقی محسوب می‌شود.',55,NULL,55,'/static/uploads/up-1785396130996-pq6fi0.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نام محصول\",\"value\":\"لوله پلی فلکس سفید سایز ۲۱\"},{\"group\":\"مشخصات پایه\",\"key\":\"سایز\",\"value\":\"۲۱\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر داخلی\",\"value\":\"۲۱ میلی‌متر\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"دارد\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر آب و رطوبت\",\"value\":\"دارد\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"کند سوز\",\"value\":\"دارد\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"طول هر حلقه\",\"value\":\"۲۵ متر\"}]','خرید لوله پلی فلکس سفید سایز ۲۱ | قیمت پلی فلکس ۲۱ میلیمتر','لوله پلی فلکس سفید سایز ۲۱ با جنس پلی‌اتیلن مقاوم در برابر UV، آب و ضربه. مناسب برای محافظت از کابل برق، شبکه و دوربین مداربسته. طول ۲۵ متر و گارانتی اصالت.\n\n','لوله پلی فلکس سفید سایز ۲۱، لوله خرطومی پلی اتیلن ۲۱، پلی فلکس ۲۱ میلیمتر، لوله پلی فلکس سفید ۲۱، قیمت پلی فلکس سایز 21، لوله خرطومی پلی فلکس 21، پلی فلکس تهران فلکس',0,'active',0,10,'[\"◉ سایز ۲۱ میلی‌متر (PG21) – قطر داخلی ۲۱ میلی‌متر، گنجایش بالا برای چند کابل\",\"◉ جنس پلی‌اتیلن مقاوم – سبک، منعطف و مقاوم در برابر ضربه و سایش\",\"◉ مقاوم در برابر اشعه UV – مناسب برای فضای باز و تابش مستقیم خورشید\",\"◉ مقاوم در برابر آب و رطوبت – عایق رطوبتی مناسب برای محیط‌های مرطوب\",\"◉ طول ۲۵ متر در هر حلقه – بسته‌بندی استاندارد\",\"◉ مناسب برای کابل برق، شبکه، تلفن و دوربین مداربسته\"]','','2026-07-29 13:11:40','2026-07-30 07:22:19',NULL),
(102,'پلی فلکس سفید سایز 25','پلی-فلکس-سفید-سایز-25','PLX-WH-25-25',18,NULL,'لوله پلی فلکس سفید سایز ۲۵ که با نام‌های لوله خرطومی پلی‌اتیلن یا پلی فلکس ۲۵ نیز شناخته می‌شود، یکی از پرکاربردترین تجهیزات محافظتی در صنعت برق، شبکه و مخابرات است. این لوله از جنس پلی‌اتیلن با کیفیت بالا (HDPE) ساخته شده و جایگزینی سبک، منعطف و مقرون‌به‌صرفه برای لوله‌های فلکسی فلزی محسوب می‌شود.\n\nلوله‌های پلی فلکس به دلیل انعطاف‌پذیری بالا، امکان عبور کابل‌ها از مسیرهای پیچیده، زوایا و فضاهای محدود را فراهم می‌کنند. سایز ۲۵ این لوله‌ها با قطر داخلی ۲۵ میلی‌متر و قطر خارجی ۲۹ میلی‌متر, برای محافظت از کابل‌های با ضخامت بیشتر یا تعداد بیشتری کابل به‌صورت همزمان، انتخاب مناسبی است.\n\n','لوله پلی فلکس سفید سایز ۲۵ یک لوله خرطومی پلی‌اتیلن با قطر داخلی ۲۵ میلی‌متر است که برای محافظت و هدایت کابل‌های برق، شبکه و دوربین مداربسته در محیط‌های داخلی و خارجی طراحی شده است. این لوله با وزن سبک، انعطاف‌پذیری بالا، مقاومت در برابر اشعه UV و رطوبت، گزینه‌ای ایده‌آل برای پروژه‌های بزرگ‌تر ساختمانی و تأسیسات برقی محسوب می‌شود.',50,NULL,5,'/static/uploads/up-1785396122516-a3y03q.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نام محصول\",\"value\":\"لوله پلی فلکس سفید سایز ۲۵\"},{\"group\":\"مشخصات پایه\",\"key\":\"سایز\",\"value\":\"۲۵\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر داخلی\",\"value\":\"۲۵ میلی‌متر\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"بله\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر آب و رطوبت\",\"value\":\"بله\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"وزن\",\"value\":\"سبک\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"محیط نصب\",\"value\":\"داخلی و بیرونی\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"طول هر حلقه\",\"value\":\"۲۵ متر\"}]','خرید لوله پلی فلکس سفید سایز ۲۵ | قیمت پلی فلکس ۲۵ میلیمتر','لوله پلی فلکس سفید سایز ۲۵ با جنس پلی‌اتیلن مقاوم در برابر UV، آب و ضربه. مناسب برای محافظت از کابل برق، شبکه و دوربین مداربسته. طول ۲۵ متر و گارانتی اصالت.\n\n','لوله پلی فلکس سفید سایز ۲۵، لوله خرطومی پلی اتیلن ۲۵، پلی فلکس ۲۵ میلیمتر، لوله پلی فلکس سفید ۲۵، قیمت پلی فلکس سایز 25، لوله خرطومی پلی فلکس 25',0,'active',0,12,'[\"◉ سایز ۲۵ میلی‌متر (PG25) – قطر داخلی ۲۵ میلی‌متر و قطر خارجی ۲۹ میلی‌متر\",\"◉ جنس پلی‌اتیلن مقاوم – سبک، منعطف و مقاوم در برابر ضربه، فشار و سایش\",\"◉ انعطاف‌پذیری بالا – عبور آسان از مسیرهای پیچیده و فضاهای محدود\",\"◉ مقاوم در برابر آب و رطوبت – عایق رطوبتی مناسب برای محیط‌های مرطوب\",\"◉ گنجایش بالا – مناسب برای کابل‌های برق اصلی و تأسیسات صنعتی\",\"◉ طول ۲۵ متر در هر حلقه – بسته‌بندی استاندارد\"]','','2026-07-29 13:17:49','2026-07-30 07:22:05',NULL),
(103,'فلکسی سفید سایز 13','فلکسی-سفید-سایز-13','FLX-WH-13-25',19,NULL,'لوله فلکسی سفید سایز ۱۳ که با نام‌های لوله خرطومی فلکسیبل، لوله فلکسی روکش‌دار یا فلکسی ۱۳ نیز شناخته می‌شود، یکی از پرکاربردترین تجهیزات محافظتی در صنعت برق، شبکه و مخابرات است. این لوله با ساختار فلزی گالوانیزه گرم و روکش PVC سفید، ترکیبی ایده‌آل از استحکام مکانیکی و مقاومت در برابر عوامل محیطی را ارائه می‌دهد.\n\nلوله‌های فلکسیبل که در لغت به معنای «انعطاف‌پذیر» هستند، به دلیل قابلیت خمش بالا، امکان عبور کابل‌ها از مسیرهای پیچیده، زوایا و فضاهای محدود را فراهم می‌کنند. سایز ۱۳ این لوله‌ها با قطر داخلی ۱۳ میلی‌متر و قطر خارجی حدود ۱۷.۵ میلی‌متر، برای محافظت از کابل‌های با ضخامت استاندارد مانند کابل‌های برق ساختمانی، کابل‌های شبکه CAT5 و CAT6، کابل‌های تلفن و کابل‌های دوربین مداربسته انتخاب مناسبی است.\n\n','لوله فلکسی سفید سایز ۱۳ (لوله خرطومی فلکسیبل) یک لوله منعطف و مقاوم با ساختار فلزی گالوانیزه و روکش PVC سفید است که برای محافظت از کابل‌های برق، شبکه، تلفن و دوربین مداربسته در برابر عوامل فیزیکی، رطوبت و شرایط جوی طراحی شده است. این محصول با قطر داخلی ۱۳ میلی‌متر، طول ۲۵ متر در هر کلاف و مقاومت در برابر اشعه UV، گزینه‌ای ایده‌آل برای محیط‌های داخلی و بیرونی می‌باشد',55,NULL,50,'/static/uploads/up-1785404667695-5dzss9.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نام محصول\",\"value\":\"لوله فلکسی سفید سایز ۱۳\"},{\"group\":\"مشخصات پایه\",\"key\":\"سایز\",\"value\":\"۱۳\"},{\"group\":\"مشخصات پایه\",\"key\":\"قطر داخلی\",\"value\":\"۱۳ میلی‌متر\"},{\"group\":\"مشخصات پایه\",\"key\":\"طول هر کلاف\",\"value\":\"۲۵ متر\"},{\"group\":\"جنس و ساختار\",\"key\":\"جنس بدنه داخلی\",\"value\":\"فولاد گالوانیزه گرم\"},{\"group\":\"جنس و ساختار\",\"key\":\"نوع روکش\",\"value\":\"PVC\"},{\"group\":\"جنس و ساختار\",\"key\":\"جنس کلی\",\"value\":\"فلزی روکش‌دار\"},{\"group\":\"مقاومت\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"بله\"},{\"group\":\"مقاومت\",\"key\":\"مقاوم در برابر خوردگی و زنگ‌زدگی\",\"value\":\"بله\"},{\"group\":\"مقاومت\",\"key\":\"مقاوم در برابر ضربه، فشار و کشش\",\"value\":\"بله\"}]','خرید لوله فلکسی سفید سایز ۱۳ | قیمت لوله خرطومی 13 میلیمتر','لوله فلکسی سفید سایز ۱۳ با روکش PVC، مقاوم در برابر UV، آب و ضربه. مناسب برای محافظت از کابل برق، شبکه و دوربین مداربسته. طول ۲۵ متر و گارانتی اصالت.\n\n','لوله فلکسی سفید سایز ۱۳، لوله خرطومی فلکسی ۱۳، لوله فلکسی ۱۳ میلیمتر، لوله فلکسی PG13.5، فلکسیبل روکشدار سفید 13، لوله فلکسی توس فلکس 13، لوله فلکسی البرز فلکس 13، لوله فلکسی تهران فلکس 13، محافظ کابل فلکسی 13',0,'active',0,12,'[\"◉ سایز ۱۳ میلی‌متر (PG13.5) – قطر داخلی ۱۳ میلی‌متر\",\"◉ مقاوم در برابر اشعه UV – مناسب برای فضای باز و تابش مستقیم خورشید\",\"◉ مقاوم در برابر آب، ضربه و فشار – محافظت کامل در محیط‌های مرطوب و صنعتی\",\"◉ طول ۲۵ متر در هر کلاف – بسته‌بندی استاندارد حلقه‌ای\",\"◉ انعطاف‌پذیری بالا (شعاع خمش ۵۰ میلی‌متر) – قابلیت خمش در مسیرهای پیچیده\",\"◉ مناسب برای کابل برق، شبکه، تلفن و دوربین مداربسته\"]',NULL,'2026-07-30 09:50:28','2026-10-01 15:18:42',NULL),
(104,'فلکسی سفید سایز 16','فلکسی-سفید-سایز-16','FLX-WH-16-25',19,NULL,'لوله فلکسی سفید سایز ۱۶ که با نام‌های لوله خرطومی فلکسیبل، لوله فلکسی روکش‌دار یا فلکسی ۱۶ نیز شناخته می‌شود، یکی از پرکاربردترین تجهیزات محافظتی در صنعت برق، شبکه و مخابرات است. این لوله با ساختار فلزی گالوانیزه گرم و روکش PVC سفید، ترکیبی ایده‌آل از استحکام مکانیکی و مقاومت در برابر عوامل محیطی را ارائه می‌دهد.\n\nلوله‌های فلکسیبل که در لغت به معنای «انعطاف‌پذیر» هستند، به دلیل قابلیت خمش بالا، امکان عبور کابل‌ها از مسیرهای پیچیده، زوایا و فضاهای محدود را فراهم می‌کنند. سایز ۱۶ این لوله‌ها با قطر داخلی ۱۶ میلی‌متر، برای محافظت از کابل‌های با ضخامت متوسط تا نسبتاً زیاد مانند کابل‌های برق ساختمانی، کابل‌های شبکه CAT5 و CAT6، کابل‌های تلفن و کابل‌های دوربین مداربسته انتخاب مناسبی است.','لوله فلکسی سفید سایز ۱۶ (لوله خرطومی فلکسیبل) یک لوله منعطف و مقاوم با ساختار فلزی گالوانیزه و روکش PVC سفید است که برای محافظت از کابل‌های برق، شبکه، تلفن و دوربین مداربسته در برابر عوامل فیزیکی، رطوبت و شرایط جوی طراحی شده است. این محصول با قطر داخلی ۱۶ میلی‌متر، طول ۲۵ متر در هر کلاف و مقاومت در برابر اشعه UV، گزینه‌ای ایده‌آل برای محیط‌های داخلی و بیرونی، تأسیسات الکتریکی و دفاتر اداری می‌باشد.',50,NULL,0,'/static/uploads/up-1785405144409-1h651m.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نام محصول\",\"value\":\"لوله فلکسی سفید سایز ۱۶\"},{\"group\":\"مشخصات پایه\",\"key\":\"سایز\",\"value\":\"۱۶\"},{\"group\":\"مشخصات پایه\",\"key\":\"طول هر کلاف\",\"value\":\"۲۵ متر\"},{\"group\":\"جنس و ساختار\",\"key\":\"جنس کلی\",\"value\":\"فلزی روکش‌دار\"},{\"group\":\"مقاومت\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"بله\"},{\"group\":\"مقاومت\",\"key\":\"مقاوم در برابر آب و رطوبت\",\"value\":\"بله\"}]','خرید لوله فلکسی سفید سایز ۱۶ | قیمت لوله خرطومی 16 میلیمتر','لوله فلکسی سفید سایز ۱۶ با روکش PVC، مقاوم در برابر UV و آب. مناسب برای محافظت از کابل برق، شبکه و دوربین مداربسته. طول ۲۵ متر و گارانتی اصالت.\n\n','لوله فلکسی سفید سایز ۱۶، لوله خرطومی فلکسی ۱۶، لوله فلکسی ۱۶ میلیمتر، لوله خرطومی برق سایز 16، فلکسیبل روکشدار سفید 16، لوله فلکسی تهران فلکس 16، لوله فلکسی توس فلکس 16، محافظ کابل فلکسی 16',0,'active',0,11,'[\"◉ سایز ۱۶ میلی‌متر (PG16) – قطر داخلی ۱۶ میلی‌متر، قطر خارجی ۲۰ میلی‌متر\",\"◉ مقاوم در برابر اشعه UV – مناسب برای فضای باز و تابش مستقیم خورشید\",\"◉ مقاوم در برابر آب، ضربه و فشار – محافظت کامل در محیط‌های مرطوب و صنعتی\",\"◉ انعطاف‌پذیری بالا – قابلیت خمش در مسیرهای پیچیده\",\"◉ طول ۲۵ متر در هر کلاف – بسته‌بندی استاندارد حلقه‌ای\",\"◉ مناسب برای کابل برق، شبکه، تلفن و دوربین مداربسته\"]',NULL,'2026-07-30 09:54:56','2026-09-11 21:05:45',NULL),
