س تهران فلکس',0,'active',0,2,'[\"◉ سایز ۱۶ میلی‌متر (PG16) – قطر داخلی ۱۶ میلی‌متر، قطر خارجی ۲۰ میلی‌متر\",\"◉ جنس پلی‌اتیلن مقاوم – سبک، منعطف و مقاوم در برابر ضربه و سایش\",\"◉ مقاوم در برابر اشعه UV – مناسب برای فضای باز و تابش مستقیم خورشید\",\"◉ مقاوم در برابر آب و رطوبت – عایق رطوبتی مناسب برای محیط‌های مرطوب\",\"◉ مناسب برای کابل برق، شبکه، تلفن و دوربین مداربسته\",\"◉ طول ۲۵ متر در هر حلقه – بسته‌بندی استاندارد با درج متراژ روی بدنه\"]',NULL,'2026-08-08 06:19:01','2026-10-01 16:42:04',NULL),
(171,'پلی فلکس مشکی سایز 21','پلی-فلکس-مشکی-سایز-21','PLX-BK-21-25',18,NULL,'لوله پلی فلکس مشکی سایز ۲۱ که با نام‌های لوله خرطومی پلی‌اتیلن یا پلی فلکس ۲۱ نیز شناخته می‌شود، یکی از پرکاربردترین تجهیزات محافظتی در صنعت برق، شبکه و مخابرات است. این لوله از جنس پلی‌اتیلن باکیفیت ساخته شده و جایگزینی سبک، منعطف و مقرون‌به‌صرفه برای لوله‌های فلکسی فلزی محسوب می‌شود.\n\nلوله‌های پلی فلکس به دلیل انعطاف‌پذیری بالا، امکان عبور کابل‌ها از مسیرهای پیچیده، زوایا و فضاهای محدود را فراهم می‌کنند. سایز ۲۱ این لوله‌ها با قطر داخلی ۲۱ میلی‌متر，گنجایش بالایی برای عبور همزمان چندین کابل یا کابل‌های با ضخامت بیشتر دارد و برای پروژه‌های بزرگ‌تر انتخاب مناسبی است.\n\n','لوله پلی فلکس مشکی سایز ۲۱ یک لوله خرطومی پلی‌اتیلن با قطر داخلی ۲۱ میلی‌متر است که برای محافظت و هدایت کابل‌های برق، شبکه و دوربین مداربسته در محیط‌های داخلی و خارجی طراحی شده است. این لوله با وزن سبک، انعطاف‌پذیری بالا، مقاومت در برابر اشعه UV و رطوبت، گزینه‌ای ایده‌آل برای پروژه‌های بزرگ‌تر ساختمانی و تأسیسات برقی محسوب می‌شود.',5,NULL,5,'/static/uploads/up-1786169960423-1xxqz0.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نام محصول\",\"value\":\"لوله پلی فلکس مشکی سایز ۲۱\"},{\"group\":\"مشخصات پایه\",\"key\":\"سایز\",\"value\":\"۲۱\"},{\"group\":\"مشخصات پایه\",\"key\":\"طول هر حلقه\",\"value\":\"۲۵ متر\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"بله\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر آب و رطوبت\",\"value\":\"بله\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"انعطاف‌پذیری\",\"value\":\"بله\"}]','خرید لوله پلی فلکس مشکی سایز ۲۱ | قیمت پلی فلکس ۲۱ میلیمتر','لوله پلی فلکس مشکی سایز ۲۱ با جنس پلی‌اتیلن مقاوم در برابر UV، آب و ضربه. مناسب برای محافظت از کابل برق، شبکه و دوربین مداربسته. طول ۲۵ متر و گارانتی اصالت.\n\n','لوله پلی فلکس مشکی سایز ۲۱، لوله خرطومی پلی اتیلن ۲۱، پلی فلکس ۲۱ میلیمتر، لوله پلی فلکس مشکی ۲۱، قیمت پلی فلکس سایز 21، لوله خرطومی پلی فلکس 21، پلی فلکس تهران فلکس',0,'active',0,3,'[\"◉ سایز ۲۱ میلی‌متر (PG21) – گنجایش بالا برای چندین کابل یا کابل‌های ضخیم\",\"◉ جنس پلی‌اتیلن مقاوم – سبک، منعطف و مقاوم در برابر ضربه و سایش\",\"◉ مقاوم در برابر اشعه UV – مناسب برای فضای باز و تابش مستقیم خورشید\",\"◉ مقاوم در برابر آب و رطوبت – عایق رطوبتی مناسب برای محیط‌های مرطوب\",\"◉ کند سوز و ایمن – مقاوم در برابر حرارت و مناسب برای تأسیسات برق\",\"◉ طول ۲۵ متر در هر حلقه – بسته‌بندی استاندارد حلقه‌ای\"]',NULL,'2026-08-08 06:46:39','2026-10-01 16:42:04',NULL),
(172,'پلی فلکس مشکی سایز 25','پلی-فلکس-مشکی-سایز-25','PLX-BK-25-25',18,NULL,'لوله پلی فلکس مشکی سایز ۲۵ که با نام‌های لوله خرطومی پلی‌اتیلن یا پلی فلکس ۲۵ نیز شناخته می‌شود، یکی از پرکاربردترین تجهیزات محافظتی در صنعت برق، شبکه و مخابرات است. این لوله از جنس پلی‌اتیلن باکیفیت ساخته شده و جایگزینی سبک، منعطف و مقرون‌به‌صرفه برای لوله‌های فلکسی فلزی محسوب می‌شود.\n\nلوله‌های پلی فلکس به دلیل انعطاف‌پذیری بالا، امکان عبور کابل‌ها از مسیرهای پیچیده، زوایا و فضاهای محدود را فراهم می‌کنند. سایز ۲۵ این لوله‌ها با قطر داخلی ۲۵ میلی‌متر و قطر خارجی ۲۹ میلی‌متر، گنجایش بالایی برای عبور همزمان چندین کابل یا کابل‌های با ضخامت بیشتر دارد و برای پروژه‌های بزرگ‌تر انتخاب مناسبی است.\n\n','لوله پلی فلکس مشکی سایز ۲۵ یک لوله خرطومی پلی‌اتیلن با قطر داخلی ۲۵ میلی‌متر است که برای محافظت و هدایت کابل‌های برق، شبکه و دوربین مداربسته در محیط‌های داخلی و خارجی طراحی شده است. این لوله با وزن سبک، انعطاف‌پذیری بالا، مقاومت در برابر اشعه UV، رطوبت و ضربه، جایگزینی مناسب و اقتصادی برای لوله‌های فلکسی فلزی محسوب می‌شود.',5,NULL,5,'/static/uploads/up-1786171621220-e5w6ic.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نام محصول\",\"value\":\"لوله پلی فلکس مشکی سایز ۲۵\"},{\"group\":\"مشخصات پایه\",\"key\":\"سایز\",\"value\":\"۲۵\"},{\"group\":\"مشخصات پایه\",\"key\":\"جنس\",\"value\":\"پلی‌اتیلن\"},{\"group\":\"مشخصات پایه\",\"key\":\"رنگ\",\"value\":\"مشکی\"},{\"group\":\"مشخصات پایه\",\"key\":\"طول هر حلقه\",\"value\":\"۲۵ متر\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر اشعه UV\",\"value\":\"بله\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"مقاوم در برابر آب و رطوبت\",\"value\":\"بله\"},{\"group\":\"مقاومت و ویژگی‌ها\",\"key\":\"انعطاف‌پذیری\",\"value\":\"بالا\"}]','خرید لوله پلی فلکس مشکی سایز ۲۵ | قیمت پلی فلکس ۲۵ میلیمتر','لوله پلی فلکس مشکی سایز ۲۵ با جنس پلی‌اتیلن مقاوم در برابر UV، آب و ضربه. مناسب برای محافظت از کابل برق، شبکه و دوربین مداربسته. طول ۲۵ متر و گارانتی اصالت.\n\n','لوله پلی فلکس مشکی سایز ۲۵، لوله خرطومی پلی اتیلن ۲۵، پلی فلکس ۲۵ میلیمتر، لوله پلی فلکس مشکی ۲۵، قیمت پلی فلکس سایز 25، لوله خرطومی پلی فلکس 25، پلی فلکس تهران فلکس',0,'active',0,4,'[\"◉ سایز ۲۵ میلی‌متر (PG25) – قطر داخلی ۲۵ میلی‌متر، قطر خارجی ۲۹ میلی‌متر\",\"◉ جنس پلی‌اتیلن مقاوم – سبک، منعطف و مقاوم در برابر ضربه و سایش\",\"◉ مقاوم در برابر اشعه UV – مناسب برای فضای باز و تابش مستقیم خورشید\",\"◉ رنگ مشکی – مناسب برای محیط‌های صنعتی و فضای باز\",\"◉ مناسب برای کابل برق، شبکه، فیبر نوری و دوربین مداربسته\",\"◉ طول ۲۵ متر در هر حلقه – بسته‌بندی استاندارد با درج متراژ روی بدنه\"]',NULL,'2026-08-08 06:51:36','2026-10-01 16:42:04',NULL),
(173,'کریمپ حرارتی 4 سانتی متر','کریمپ-حرارتی-4-سانتی-متر','CRMP-HS-40-100',71,NULL,'کریمپ حرارتی ۴ سانتی‌متری (۴۰ میلی‌متری) که با نام‌های شرینک حرارتی (Heat Shrink) یا محافظ فیوژن نیز شناخته می‌شود، یک قطعه پلاستیکی و فلزی است که به‌عنوان محافظ فیوژن فیبر نوری شناخته می‌شود. این محصول یک وسیله واجب و ضروری در کیف ابزار هر فیوژن‌کار حرفه‌ای است.\n\nاین قطعه از دو بخش اصلی تشکیل شده است:\n۱. لوله پلاستیکی شفاف که با حرارت منقبض می‌شود و عایق‌بندی را انجام می‌دهد.\n۲. میله استیل ضد زنگ درون لوله که از خم‌شدن و شکستگی محل جوش جلوگیری می‌کند.','کریمپ حرارتی ۴ سانتی‌متری (۴۰ میلی‌متری) با قطر ۳ میلی‌متر، یک قطعه یکبارمصرف و ضروری برای محافظت از محل فیوژن فیبر نوری است. این قطعه با قرارگیری روی محل جوش و حرارت‌دیدن، از ایجاد شکستگی جلوگیری کرده و محل اتصال را در برابر رطوبت و گرد و غبار عایق‌بندی می‌کند. مناسب برای فیوژن‌کاران حرفه‌ای و پروژه‌های FTTH.',5,NULL,50,'/static/uploads/up-1786172834209-kdt94b.webp','[]','[{\"group\":\"ابعاد\",\"key\":\"طول\",\"value\":\"۴ سانتی‌متر (۴۰ میلی‌متر)\"},{\"group\":\"ابعاد\",\"key\":\"قطر\",\"value\":\"۳ میلی‌متر\"},{\"group\":\"ابعاد\",\"key\":\"قطر داخلی (حدود)\",\"value\":\"۱.۰ تا ۱.۵ میلی‌متر\"},{\"group\":\"جنس\",\"key\":\"لوله بیرونی\",\"value\":\"پلاستیک شفاف (پلی‌اولفین)\"},{\"group\":\"جنس\",\"key\":\"میله داخلی\",\"value\":\"استیل ضد زنگ\"},{\"group\":\"کاربرد\",\"key\":\"روش نصب\",\"value\":\"قرارگیری روی محل فیوژن و حرارت‌دهی با دستگاه فیوژن\"}]','خرید کریمپ حرارتی ۴ سانتی‌متری | قیمت شرینک فیبر نوری 100 عددی','کریمپ حرارتی ۴ سانتی‌متری (۴۰ میلی‌متر) با قطر ۳ میلی‌متر، دارای میله استیل ضد زنگ و لوله شفاف. مناسب برای محافظت از محل فیوژن فیبر نوری در برابر شکستگی، رطوبت و گرد و غبار. بسته ۱۰۰ عددی با گارانتی اصالت.','کریمپ حرارتی ۴ سانتی، کریمپ حرارتی ۴۰ میلی‌متر، شرینک فیبر نوری 4cm، محافظ فیوژن، Heat Shrink 40mm، کریمپ فیبر نوری، کریمپ حرارتی 100 عددی',0,'active',0,2,'[\"◉ طول ۴ سانتی‌متر (۴۰ میلی‌متر) – اندازه جمع‌وجور برای فضاهای محدود\",\"◉ قطر ۳ میلی‌متر – استاندارد و سازگار با اکثر فیبرهای نوری\",\"◉ دارای میله استیل ضد زنگ – جلوگیری از خم‌شدن و شکستگی محل جوش\",\"◉ لوله پلاستیکی شفاف – قابلیت مشاهده محل فیوژن و عایق‌بندی کامل\",\"◉ مقاوم در برابر رطوبت و گرد و غبار – محافظت طولانی‌مدت از اتصال فیبر\",\"◉ بسته‌بندی ۱۰۰ عددی – مقرون‌به‌صرفه برای فیوژن‌کاران حرفه‌ای\"]',NULL,'2026-08-08 07:11:15','2026-10-01 16:42:04',NULL),
(174,'کریمپ حرارتی 6 سانتی متر','کریمپ-حرارتی-6-سانتی-متر','CRMP-HS-60-100',71,NULL,'کریمپ حرارتی یا شرینک (Heat Shrink) یک قطعه پلاستیکی و فلزی است که به‌عنوان محافظ فیوژن فیبر نوری شناخته می‌شود. این محصول یک وسیله واجب و ضروری در کیف ابزار هر فیوژن‌کار حرفه‌ای است. این قطعه از دو بخش اصلی تشکیل شده است:\n\nلوله پلاستیکی شفاف و بی‌رنگ که با حرارت منقبض می‌شود و عایق‌بندی را انجام می‌دهد.\n\nمیله استیل ضد زنگ درون لوله که از خم‌شدن و شکستگی محل جوش جلوگیری می‌کند.','کریمپ حرارتی ۶ سانتی‌متری (۶۰ میلی‌متری) یک قطعه ضروری و حیاتی برای هر فیوژن‌کار حرفه‌ای است. این قطعه که به‌عنوان محافظ فیوژن فیبر نوری شناخته می‌شود، برای ایجاد محافظت مکانیکی و عایق‌بندی در محل اتصال (جوش) دو فیبر نوری استفاده می‌شود. این محصول در بسته‌های ۱۰۰ عددی عرضه شده و با قرارگیری بر روی محل فیوژن و حرارت‌دیدن، از ایجاد شکستگی و آسیب به تارهای فیبر نوری جلوگیری می‌کند.',5,NULL,5,'/static/uploads/up-1786173130177-0gzyo7.jpg','[]','[{\"group\":\"ابعاد و فیزیکی\",\"key\":\"طول\",\"value\":\"۶ سانتی‌متر (۶۰ میلی‌متر)\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"قطر\",\"value\":\"۳ میلی‌متر\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"جنس لوله بیرونی\",\"value\":\"پلاستیک شفاف و بی‌رنگ (پلی‌اولفین)\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"جنس میله داخلی\",\"value\":\"استیل ضد زنگ\"},{\"group\":\"ابعاد و فیزیکی\",\"key\":\"بسته‌بندی\",\"value\":\"بسته ۱۰۰ عددی\"}]','خرید کریمپ حرارتی ۶ سانتی | قیمت شرینک فیبر نوری 100 عددی','کریمپ حرارتی ۶ سانتی‌متری (شرینک فیبر نوری) بسته ۱۰۰ عددی با قطر ۳ میلی‌متر. محافظت از محل فیوژن در برابر شکستگی، رطوبت و گرد و غبار. مناسب برای فیوژن‌کاران حرفه‌ای. گارانتی اصالت و ارسال سریع.\n\n','کریمپ حرارتی، شرینک فیبر نوری، محافظ فیوژن، Heat Shrink، کریمپ فیبر نوری، کریمپ ۶ سانتی، کریمپ ۶۰ میلی‌متری',0,'active',0,2,'[\"◉ طول ۶ سانتی‌متر (۶۰ میلی‌متر) – اندازه استاندارد برای محافظت از محل فیوژن\",\"◉ قطر ۳ میلی‌متر – سازگار با اکثر فیبرهای نوری\",\"◉ دارای میله استیل ضد زنگ – جلوگیری از خم‌شدن و شکستگی محل جوش\",\"◉ لوله پلاستیکی شفاف – قابلیت مشاهده محل فیوژن و عایق‌بندی کامل\",\"◉ مقاوم در برابر رطوبت و گرد و غبار – محافظت طولانی‌مدت از اتصال فیبر\",\"◉ بسته‌بندی ۱۰۰ عددی – مقرون‌به‌صرفه برای فیوژن‌کاران حرفه‌ای\"]',NULL,'2026-08-08 08:35:44','2026-10-01 16:42:04',NULL),
(175,'آداپتور فیبر نوری SC سینگل مود سیمپلکس','آداپتور-فیبر-نوری-sc-سینگل-مود-سیمپلکس','ADP-SC-SM-SIMPLEX-001',70,11,'آداپتور فیبر نوری SC-SC سیمپلکس سینگل مود، یک قطعه حیاتی در زیرساخت شبکه‌های فیبر نوری است که به عنوان یک رابط (Interface) برای اتصال دو کانکتور فیبر نوری از نوع SC به یکدیگر عمل می‌کند.\n\nاین آداپتور که گاهی با نام کوپلر (Coupler) نیز شناخته می‌شود، در واقع یک بوش (Female-Female) است که دو کانکتور نر (Male) SC را به هم متصل کرده و فیبرهای نوری داخل آن‌ها را دقیقاً در مقابل هم قرار می‌دهد تا نور با حداقل تلفات ممکن از یکی به دیگری منتقل شود.','آداپتور فیبر نوری SC-SC سیمپلکس سینگل مود، یک قطعه اتصال دهنده (کوپلر) است که برای اتصال دقیق و با تلفات کم دو کانکتور فیبر نوری از نوع SC به یکدیگر استفاده می‌شود. این آداپتور با طراحی سیمپلکس (تک کاناله) و سازگاری با فیبرهای سینگل مود (Single-mode / OS2)، برای اتصال پچ کوردها در پچ پنل‌ها، ODFها، باکس‌های فیوژن و تجهیزات مخابراتی کاربرد گسترده‌ای دارد.',5,NULL,5,'/static/uploads/up-1786178263285-bafxpo.webp','[]','[{\"group\":\"مشخصات پایه\",\"key\":\"نوع محصول\",\"value\":\"آداپتور / کوپلر فیبر نوری\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کانکتور\",\"value\":\"SC (هر دو سر)\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کارکرد\",\"value\":\"سیمپلکس\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع فیبر قابل اتصال\",\"value\":\"سینگل مود\"}]','خرید آداپتور فیبر نوری SC سینگل مود سیمپلکس | قیمت SC-SC','آداپتور فیبر نوری SC-SC سیمپلکس سینگل مود با تلفات ورودی کم و قابلیت اطمینان بالا. مناسب برای اتصال پچ کوردها در پچ پنل و ODF. ارسال سریع و گارانتی اصالت.\n\n','آداپتور فیبر نوری SC، آداپتور SC سیمپلکس، آداپتور سینگل مود، کوپلر فیبر نوری SC، SC-SC adapter، single mode fiber adapter، تجهیزات فیبر نوری',0,'active',0,4,'[]',NULL,'2026-08-08 08:45:47','2026-10-01 16:42:04',NULL),
(176,'آداپتور فیبر نوری SC سینگل مود داپلکس','آداپتور-فیبر-نوری-sc-سینگل-مود-داپلکس','ADP-SC-SM-DUPLEX-001',69,NULL,'آداپتور فیبر نوری SC-SC داپلکس سینگل مود، یک المان کلیدی در لایه فیزیکی (Physical Layer) شبکه‌های نوری محسوب می‌شود. این قطعه پسیو (Passive) که به عنوان یک واسط (Interface) عمل می‌کند، امکان جفت‌سازی دقیق دو جفت کانکتور SC را در یک محفظه واحد فراهم می‌آورد. هدف اصلی آن، ایجاد هم‌محوری کامل بین هسته‌های ۹ میکرونی فیبرهای سینگل مود است تا انتقال سیگنال‌های نوری با پهنای باند بالا (بالای ۱۰۰ گیگابیت) با حداقل انعکاس و تضعیف صورت گیرد.\n\n','آداپتور فیبر نوری SC-SC داپلکس سینگل مود، یک کوپلر غیرفعال دوکاناله با آستین‌های سرامیکی زیرکونیا است که برای ایجاد اتصالی پایدار، با تلفات کمتر از ۰.۲ دسی‌بل و بازگشت بیش از ۵۰ دسی‌بل، بین دو جفت کانکتور SC در شبکه‌های مخابراتی، دیتاسنترها و پروژه‌های FTTH طراحی و ساخته شده است.',5,NULL,5,'/static/uploads/up-1786271804228-i3gmns.webp','[]','[]','خرید آداپتور فیبر نوری SC داپلکس سینگل مود | قیمت SC-SC','آداپتور SC-SC داپلکس سینگل مود با تلفات ۰.۲dB و آستین سرامیکی. مناسب برای پچ پنل، ODF و سوئیچ‌های نوری. دارای گارانتی اصالت و ارسال فوری.\n\n','آداپتور فیبر نوری SC داپلکس، کوپلر SC دوکاناله، آداپتور سینگل مود داپلکس، SC duplex adapter، OS2 adapter، تجهیزات پسیو فیبر نوری، قیمت آداپتور SC',0,'active',0,2,'[]','','2026-08-09 06:42:36','2026-10-01 16:42:04',NULL),
(177,'پچ پنل 24 پورت فیبر نوری مدل SC','پچ-پنل-24-پورت-فیبر-نوری-مدل-sc','PNL-SC-SM-24P-001',73,NULL,'پچ پنل ۲۴ پورت فیبر نوری SC سینگل مود، یکی از اجزای اساسی در زیرساخت شبکه‌های فیبر نوری است که به عنوان یک نقطه مرکزی برای مدیریت، سازماندهی و توزیع اتصالات فیبر نوری عمل می‌کند. این پچ پنل با طراحی استاندارد ۱۹ اینچی و ارتفاع ۱ یونیت، امکان نصب در رک‌های شبکه و تجهیزات مخابراتی را فراهم می‌کند.\n\nپچ پنل فیبر نوری، نقطه تلاقی کابل‌های فیبر نوری ورودی (از سمت شبکه اصلی یا ODF) و پچ کوردهای خروجی (به سمت تجهیزات فعال شبکه مانند سوئیچ‌ها و روترها) است. این محصول با داشتن ۲۴ پورت SC، امکان اتصال و قطع آسان فیبرها را بدون نیاز به جوشکاری مجدد فراهم می‌کند.\n\n','پچ پنل ۲۴ پورت فیبر نوری SC سینگل مود، یک راه‌حل مدیریت کابل و توزیع اتصالات فیبر نوری در مراکز داده و تابلوهای مخابراتی است. این پچ پنل با طراحی استاندارد ۱۹ اینچی، قابلیت نصب در رک و تجهیزات شبکه را داشته و با داشتن ۲۴ پورت SC (سیمپلکس یا داپلکس)، امکان سازماندهی، حفاظت و اتصال آسان فیبرهای نوری را فراهم می‌کند.',5,NULL,5,'/static/uploads/up-1786272305780-qsqy00.webp','[\"/static/uploads/up-1786272310245-8bpr7j.webp\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"نوع محصول\",\"value\":\"پچ پنل فیبر نوری\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد پورت\",\"value\":\"۲۴ پورت\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کانکتور\",\"value\":\"SC\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع فیبر قابل اتصال\",\"value\":\"سینگل مود\"},{\"group\":\"مشخصات پایه\",\"key\":\"ارتفاع رک\",\"value\":\"۱ یونیت\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"عرض\",\"value\":\"۴۸۲.۶ میلی‌متر\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"ارتفاع\",\"value\":\"۴۴.۴۵ میلی‌متر\"}]','خرید پچ پنل ۲۴ پورت فیبر نوری SC سینگل مود | قیمت پچ پنل','پچ پنل ۲۴ پورت فیبر نوری SC سینگل مود با طراحی ۱۹ اینچی و قابلیت نصب در رک. مناسب برای مدیریت و توزیع اتصالات فیبر نوری در دیتاسنتر و ODF. ارسال سریع و گارانتی اصالت.\n\n','پچ پنل فیبر نوری، پچ پنل ۲۴ پورت SC، پچ پنل سینگل مود، patch panel fiber optic، SC patch panel، مدیریت فیبر نوری، تجهیزات فیبر نوری',0,'active',0,3,'[\"◉ ۲۴ پورت SC (سیمپلکس یا داپلکس) برای اتصالات فیبر نوری\",\"◉ سازگار با فیبر سینگل مود (Single-mode / OS2)\",\"◉ ارتفاع ۱ یونیت (1U) – مناسب برای استفاده در دیتاسنترها\",\"◉ قابلیت نصب آداپتورهای SC با رنگ‌بندی آبی (UPC) یا سبز (APC)\",\"◉ مجهز به محافظ گرد و غبار برای تمامی پورت‌ها\"]',NULL,'2026-08-09 11:49:52','2026-10-01 16:42:04',NULL),
(178,'پچ پنل 12 پورت فیبر نوری مدل SC','پچ-پنل-12-پورت-فیبر-نوری-مدل-sc','PNL-SC-SM-12P-001',73,NULL,NULL,'پچ پنل ۱۲ پورت فیبر نوری SC سینگل مود، یک راه‌حل مدیریت کابل و توزیع اتصالات فیبر نوری در پروژه‌های کوچک تا متوسط است. این پچ پنل با طراحی استاندارد ۱۹ اینچی و ارتفاع ۱ یونیت، قابلیت نصب در رک را داشته و با داشتن ۱۲ پورت SC (سیمپلکس یا داپلکس)، امکان سازماندهی، حفاظت و اتصال آسان فیبرهای نوری را در فضاهای محدود فراهم می‌کند.',5,NULL,5,'/static/uploads/up-1786276256277-zqfcnt.webp','[\"/static/uploads/up-1786276281504-mr6vno.webp\",\"/static/uploads/up-1786276285983-0m7wju.webp\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"نوع محصول\",\"value\":\"پچ پنل فیبر نوری\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد پورت\",\"value\":\"۱۲ پورت\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع فیبر قابل اتصال\",\"value\":\"سینگل مود\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"ارتفاع رک\",\"value\":\"۱ یونیت\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"عرض\",\"value\":\"۴۸۲.۶ میلی‌متر\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"ارتفاع\",\"value\":\"۴۴.۴۵ میلی‌متر\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"عمق\",\"value\":\"۲۰۰ تا ۲۵۰ میلی‌متر\"}]','خرید پچ پنل ۱۲ پورت فیبر نوری SC سینگل مود | قیمت پچ پنل','پچ پنل ۱۲ پورت فیبر نوری SC سینگل مود با طراحی ۱۹ اینچی و ۱ یونیت. مناسب برای مدیریت اتصالات فیبر نوری در دیتاسنترهای کوچک و ODF. ارسال سریع و گارانتی اصالت.\n\n','پچ پنل فیبر نوری، پچ پنل ۱۲ پورت SC، پچ پنل سینگل مود، patch panel fiber optic، SC patch panel، مدیریت فیبر نوری، تجهیزات فیبر نوری',0,'active',0,4,'[\"◉ ۱۲ پورت SC (سیمپلکس یا داپلکس) برای اتصالات فیبر نوری\",\"◉ سازگار با فیبر سینگل مود (Single-mode / OS2)\",\"◉ ارتفاع ۱ یونیت (1U) – مناسب برای استفاده در فضاهای محدود\",\"◉ دارای غلطک‌های هدایت کننده و نگهدارنده کابل در پشت\",\"◉ جنس بدنه از فولاد با پوشش الکترواستاتیک (ضد خش و مقاوم)\",\"◉ مجهز به محافظ گرد و غبار برای تمامی پورت‌ها\"]',NULL,'2026-08-09 11:54:49','2026-10-01 16:42:04',NULL),
(179,'پچ پنل 6 پورت فیبر نوری مدل SC','پچ-پنل-6-پورت-فیبر-نوری-مدل-sc','PNL-SC-SM-6P-001',73,NULL,'پچ پنل ۶ پورت فیبر نوری SC سینگل مود، یکی از اجزای اساسی در زیرساخت شبکه‌های فیبر نوری با ابعاد بسیار کوچک است که به عنوان یک نقطه مرکزی برای مدیریت، سازماندهی و توزیع اتصالات فیبر نوری عمل می‌کند. این پچ پنل با طراحی استاندارد ۱۹ اینچی و ارتفاع ۱ یونیت، امکان نصب در رک‌های شبکه و تجهیزات مخابراتی را فراهم می‌کند.\n\nپچ پنل فیبر نوری، نقطه تلاقی کابل‌های فیبر نوری ورودی (از سمت شبکه اصلی یا ODF) و پچ کوردهای خروجی (به سمت تجهیزات فعال شبکه مانند سوئیچ‌ها و روترها) است. این محصول با داشتن ۶ پورت SC، امکان اتصال و قطع آسان فیبرها را بدون نیاز به جوشکاری مجدد فراهم می‌کند.\n\n','پچ پنل ۶ پورت فیبر نوری SC سینگل مود، یک راه‌حل جمع‌وجور و کارآمد برای مدیریت کابل و توزیع اتصالات فیبر نوری در پروژه‌های کوچک است. این پچ پنل با طراحی استاندارد ۱۹ اینچی و ارتفاع ۱ یونیت، قابلیت نصب در رک را داشته و با داشتن ۶ پورت SC (سیمپلکس یا داپلکس)، امکان سازماندهی، حفاظت و اتصال آسان فیبرهای نوری را در فضاهای بسیار محدود فراهم می‌کند.',5,NULL,5,'/static/uploads/up-1786276528684-tuoo3x.webp','[\"/static/uploads/up-1786276598456-k03p3l.webp\"]','[{\"group\":\"مشخصات پایه\",\"key\":\"نوع محصول\",\"value\":\"پچ پنل فیبر نوری\"},{\"group\":\"مشخصات پایه\",\"key\":\"تعداد پورت\",\"value\":\"۶ پورت\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع کانکتور\",\"value\":\"SC\"},{\"group\":\"مشخصات پایه\",\"key\":\"نوع فیبر قابل اتصال\",\"value\":\"سینگل مود\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"ارتفاع رک\",\"value\":\"۱ یونیت\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"عرض\",\"value\":\"۴۸۲.۶ میلی‌متر (۱۹ اینچ استاندارد)\"},{\"group\":\"ابعاد فیزیکی\",\"key\":\"ارتفاع\",\"value\":\"۴۴.۴۵ میلی‌متر (۱ یونیت)\"}]','خرید پچ پنل ۶ پورت فیبر نوری SC سینگل مود | قیمت پچ پنل','پچ پنل ۶ پورت فیبر نوری SC سینگل مود با طراحی ۱۹ اینچی و ۱ یونیت. مناسب برای مدیریت اتصالات فیبر نوری در پروژه‌های کوچک و ODF. ارسال سریع و گارانتی اصالت.\n\n','پچ پنل فیبر نوری، پچ پنل ۶ پورت SC، پچ پنل سینگل مود، patch panel fiber optic، SC patch panel، مدیریت فیبر نوری، تجهیزات فیبر نوری',0,'active',0,3,'[\"◉ ۶ پورت SC (سیمپلکس یا داپلکس) برای اتصالات فیبر نوری\",\"◉ سازگار با فیبر سینگل مود (Single-mode / OS2)\",\"◉ طراحی استاندارد ۱۹ اینچی با قابلیت نصب در رک\",\"◉ دارای غلطک‌های هدایت کننده و نگهدارنده کابل در پشت\",\"◉ جنس بدنه از فولاد با پوشش الکترواستاتیک (ضد خش و مقاوم)\",\"◉ مجهز به محافظ گرد و غبار برای تمامی پورت‌ها\"]',NULL,'2026-08-09 12:00:42','2026-10-01 16:42:04',NULL);
