INSERT INTO `posts` (`id`, `title`, `slug`, `excerpt`, `content`, `cover_image`, `author_id`, `category`, `tags`, `status`, `views`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`) VALUES (1,'راهنمای انتخاب ماژول SFP مناسب برای شبکه فیبر نوری','sfp-module-guide','تفاوت ماژول‌های سینگل‌مود و مالتی‌مود، برد و طول موج را بشناسید.','<p>ماژول‌های SFP نقش مهمی در شبکه‌های فیبر نوری دارند. در این مقاله تفاوت سینگل‌مود و مالتی‌مود و نکات انتخاب را بررسی می‌کنیم.</p><h3>سینگل‌مود یا مالتی‌مود؟</h3><p>برای مسافت‌های طولانی از سینگل‌مود و برای مسافت‌های کوتاه از مالتی‌مود استفاده می‌شود.</p>','/static/images/blog1.svg',1,'فیبر نوری',NULL,'published',40,NULL,NULL,NULL,'2026-07-04 23:12:19','2026-10-01 16:42:03'),
(2,'تفاوت WiFi 5 و WiFi 6 در شبکه‌های سازمانی','wifi5-vs-wifi6','چرا باید به WiFi 6 ارتقا دهید؟ مزایا و سناریوهای کاربردی.','<p>استاندارد WiFi 6 با ظرفیت بالاتر، تأخیر کمتر و پوشش بهتر طراحی شده است.</p>','/static/images/blog2.svg',1,'وایرلس',NULL,'published',13,NULL,NULL,NULL,'2026-07-04 23:12:19','2026-10-01 16:42:03'),
(3,'فایروال نسل جدید (NGFW) چیست و چه تفاوتی دارد؟','ngfw-introduction','قابلیت‌های IPS، کنترل اپلیکیشن و SSL Inspection را بشناسید.','<p>فایروال‌های NGFW علاوه بر فیلترینگ معمولی، قابلیت‌های IPS، Application Control و SSL Inspection را دارند.</p>','/static/images/blog3.svg',1,'امنیت شبکه',NULL,'published',13,NULL,NULL,NULL,'2026-07-04 23:12:19','2026-10-01 16:42:03');
